export const CHAPTERS: BookChapter[] = [
  {
    id: "intro", number: 0, free: true, icon: "book", color: "#64D2FF", readMin: 2, part: "I. Как работает ловушка",
    titleRu: "Прежде чем начать",
    leadRu: "Это не курс лечения и не список запретов — это разговор начистоту о том, как на самом деле устроена сигарета в твоей жизни.",
    bodyRu: [{"type":"p","text":"Сразу договоримся: тут никто не будет качать головой и показывать чёрные лёгкие на плакате. Ты и так всё это видел. Если бы страшилки работали, ты бы дочитывал эту книгу некурящим."},{"type":"p","text":"Это просто честный разговор. Как на кухне поздним вечером, когда можно не притворяться, что у тебя всё под контролем."},{"type":"h","text":"Одна деталь меняет всё"},{"type":"p","text":"Представь, что ты годами носишь в кармане камешек и думаешь, что он приносит удачу. А потом кто-то показывает: камешек обычный, а удача случалась сама по себе. Выбросить его становится легко — не потому, что ты собрался с духом, а потому что ты перестал в него верить."},{"type":"p","text":"С тягой так же. Когда поймёшь, как именно она устроена и что на самом деле обещает, многое перестанет держать тебя за рукав. Об этом — следующая глава, и да, сила воли там окажется не на главной роли."},{"type":"h","text":"Как читать"},{"type":"p","text":"По одной главе. Не залпом. Прочитал — и примерь на свой вчерашний день: где была сигарета, что ты в тот момент чувствовал, что она тебе будто бы дала. Книга работает, когда ты сверяешь её не с теорией, а со своей пепельницей."},{"type":"p","text":"Бросать тяжелее всего в первые дни. Дальше тяга приходит волнами — короче, реже, слабее. Это не недели сплошной пытки, это процесс, который идёт на спад. А если сорвёшься — это не провал и не возврат к нулю. Скорее зацепка: ты узнал, какой момент тебя ловит. И счётчик в Бризе из-за одной сигареты не обнулится — он считает путь, а не безупречность."},{"type":"h","text":"Книга и приложение"},{"type":"p","text":"Эта книга и Бриз — про одно и то же, просто с разных сторон: тут объясняется, там тебя ведут день за днём. Держи их рядом — так понятнее."},{"type":"p","text":"И сразу честно про рамки: это образовательный текст и поддержка, а не медицинский совет, и он не заменяет живого врача. Если решишь добавить пластырь, жвачку или таблетки — это не белый флаг и не подпорка для слабых, а просто ещё один инструмент, который работает в связке с пониманием, а не вместо тебя. А всё рецептурное — спокойно и только через врача, без самодеятельности."},{"type":"p","text":"Дальше — почему держаться зубами не обязательно, как тяга обманывает и что делать вместо борьбы. Переверни страницу."}],
    takeawayRu: "Тебя держит не сигарета, а вера в неё. Эта книга — про то, как перестать верить.",
  },
  {
    id: "willpower", number: 1, icon: "hand", color: "#BF5AF2", readMin: 5, part: "I. Как работает ловушка",
    titleRu: "Сила воли — не главное",
    leadRu: "Ты не слабый. Тебя просто учили решать задачу не тем инструментом.",
    bodyRu: [{"type":"p","text":"Тебе наверняка хоть раз говорили: «Захочешь — бросишь. Это же дело характера». И ты, может, киваешь, а внутри что-то сжимается. Потому что характер у тебя вообще-то есть. Ты тянешь работу, держишь слово, встаёшь по будильнику в темноте зимой. А вот с сигаретой — почему-то снова и снова осечка. И напрашивается вывод: значит, со мной что-то не так."},{"type":"p","text":"Так вот. С тобой всё так. Просто тебе подсунули неверную задачу и неверный инструмент для неё."},{"type":"h","text":"«Бросают сильные» — и почему это враньё"},{"type":"p","text":"Есть удобный миф: курят слабаки, а бросают волевые. Звучит логично — и поэтому особенно вредно. Из него следует, что если ты не бросил, ты в команде слабых. И ты тихо в это веришь, и от этого ещё тяжелее: зачем пытаться, если у тебя «не тот материал»."},{"type":"p","text":"Оглянись вокруг. Курят хирурги, которые по восемь часов стоят над столом. Курят матери троих детей, которые не спали нормально лет пять. Курят люди, которые в зале жмут штангу, какую ты и не поднимешь. Это что, слабохарактерные? Да они выносливее половины некурящих. Курение вообще не выбирает по силе. Оно цепляет всех подряд — потому что держит не характер, а химия и привычка, замаскированная под «мне это нужно»."},{"type":"p","text":"И наоборот: люди, которые легко бросили, часто рассказывают об этом без всякого героизма. Не «я стиснул зубы», а «в какой-то момент просто перестало быть нужно». Заметь разницу. Не перетерпели. Перестало быть нужно."},{"type":"h","text":"Глянь, что такое воля, если её разобрать"},{"type":"p","text":"Сила воли — это когда ты хочешь чего-то и при этом запрещаешь себе это получить. Хочешь поспать — встаёшь. Хочешь торт — отодвигаешь тарелку. Хочешь закурить — терпишь. То есть воля всегда работает поверх желания. Желание никуда не делось, ты просто давишь его сверху ладонью."},{"type":"p","text":"Попробуй так подержать. Минуту — легко. Час — уже напряжно. А неделю? Месяц? Год? Это как держать дверь, в которую кто-то ломится с той стороны. Сначала ты бодр и упёрся ногой. Потом устаёшь. Потом устаёшь от того, что устал. И в какой-то обычный вторник, когда на работе аврал и нет сил даже на ужин, рука сама тянется — и дверь распахивается. Не потому что ты слабак. Потому что держать дверь бесконечно физически нельзя."},{"type":"p","text":"Вот почему «бросаю на силе воли» так часто заканчивается срывом. Не оттого, что воли не хватило. Оттого, что воля — неподходящий инструмент для этой работы. Ей просто нечем тут зацепиться надолго."},{"type":"h","text":"Пока сигарета будто что-то даёт — ты в режиме лишения"},{"type":"p","text":"Тут самое важное. Если ты в глубине души считаешь, что сигарета тебя успокаивает, помогает сосредоточиться, делает паузу приятнее — то, бросая, ты у себя что-то отбираешь. Хорошее. И всё бросание превращается в одну длинную тоску по утраченному. Ты сидишь и грустишь по другу, которого «пришлось прогнать». Естественно, тебя к нему тянет обратно."},{"type":"p","text":"Но взгляни на это трезво. Сигарета не успокаивает по-настоящему — между затяжками никотин уходит, поднимается лёгкая тревога, и следующая сигарета просто гасит её до нуля. А ты принимаешь это короткое «отпустило» за подарок. Это как чесать комариный укус: на секунду легче, а потом зудит сильнее, и ты чешешь снова. Облегчение настоящее. Только зуд устроила та же рука, которая теперь его «лечит». Перестань чесать совсем — и через пару дней забудешь, что укус вообще был."},{"type":"p","text":"Пока ты этого не увидел, любой метод — это борьба. Увидел — и бороться становится не с чем."},{"type":"h","text":"Зачем тогда эта книга"},{"type":"p","text":"Цель «Выдоха» — не выдать тебе запас терпения побольше, чтобы ты дольше держал ту самую дверь. Цель — спокойно, без нравоучений, разобрать вместе с тобой, что сигарета даёт на самом деле, а что только обещает. Чтобы желание ушло не из-под палки, а само — потому что отпала причина."},{"type":"p","text":"Когда в сигарете перестаёшь видеть что-то ценное, проходить мимо неё обычно становится легко — без всякого геройства. Примерно как ты без усилий проходишь мимо вещей, которые тебе просто не нужны. Это не насилие над собой. Это свобода."},{"type":"p","text":"Да, первые дни без курева бывают неуютными — тело отвыкает, накатывают волны желания. Но они короче и слабее, чем ты боишься, и подробнее про них — в отдельной главе про ломку. И сразу скажу: воля тут не отменяется. Она просто перестаёт быть единственным, на чём всё держится. Когда понимаешь, что сигарета тебе не друг, тебе уже не нужно держать дверь — её незачем держать."},{"type":"p","text":"Есть и аптечные помощники — никотиновые пластыри, жвачки, рецептурные препараты (рецептурное — только с врачом). Они не белый флаг и не подпорка для слабых, а способ сбить остроту первых волн, пока к тебе приходит то самое понимание. А если когда-нибудь сорвёшься — это не крах и не приговор тебе. Это просто отметка на карте: вот здесь, в этом месте, оказалось скользко. С этим мы спокойно разберёмся дальше. Это образовательный текст, а не медицинский совет."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Вспомни последнюю сигарету, которую ты выкурил. Где ты был, что чувствовал за минуту до неё? А теперь честно, одним словом про себя: что она реально изменила через пять минут после? Не торопись с ответом — просто посмотри. Это первый кирпич, который мы вынимаем из стены."}],
    takeawayRu: "Воля — это держать дверь, в которую ломятся. Свобода — это когда за дверью уже никого нет.",
  },
  {
    id: "trap", number: 2, icon: "bolt", color: "#FF9500", readMin: 4, part: "I. Как работает ловушка",
    titleRu: "Откуда берётся тяга",
    leadRu: "Сигарета не убирает дискомфорт — она его и поставляет, а потом берёт с тебя плату за паузу.",
    bodyRu: [{"type":"p","text":"В прошлой главе мы договорились: воля тут не главный герой. Но если дело не в силе характера — тогда в чём? Почему миллионы спокойных, взрослых, неглупых людей раз за разом тянутся к пачке, хотя сами же ругают себя за это? Ответ проще и неприятнее, чем кажется. Дело в том, как устроен сам механизм."},{"type":"h","text":"Откуда берётся «надо»"},{"type":"p","text":"Представь обычный день. Ты докурил, погасил, занялся делами. Проходит час, может полтора — и где-то на фоне включается лёгкое неудобство. Не боль, не паника. Скорее как мелкий зуд, который не чешется. Чуть пустовато внутри, чуть нечем занять руки, мысль то и дело сворачивает в сторону балкона или курилки. Ты, скорее всего, объясняешь это по-своему: устал, день нервный, начальник достал, погода давит."},{"type":"p","text":"А правда в том, что многое из этого — не про начальника. Реальный стресс, конечно, никто не отменял, он накладывается сверху. Но есть и нижний слой, который ты обычно не замечаешь: никотин в крови убывает, тело привыкло к нему и теперь чувствует, что его не хватает. Это не «нервы» и не слабость воли — это обычное отвыкание, которое идёт между затяжками, тихо, в фоне. Тот самый дискомфорт, который ты привык глушить, в немалой части создан предыдущей сигаретой. Не только работой. Не только жизнью. Ещё и сигаретой, которую ты выкурил час назад."},{"type":"h","text":"Облегчение из пустоты"},{"type":"p","text":"И вот ты закуриваешь. И правда становится легче — это не выдумка, ощущение настоящее. Только присмотрись, что именно произошло. Тебе не добавили чего-то хорошего. У тебя забрали то плохое, что несколько минут назад поставила прошлая сигарета. Ты вернулся в ноль. В точку, где у тебя ничего не зудит и не сосёт под ложечкой. И этот возврат в ноль мозг записывает как кайф, как награду, как «ну вот, отпустило»."},{"type":"p","text":"А теперь самое неудобное. Человек, который не курит, живёт в этом самом нуле постоянно. Бесплатно. Без ритуала, без поиска зажигалки, без выхода на мороз. У него нет этой ямки, которую надо засыпать каждый час, — потому что её некому копать. То спокойствие, за которым ты гоняешься с пачкой, у него просто фоновое состояние. Курильщик платит деньгами, временем и здоровьем за то, чтобы изредка дотягиваться до того, что у некурящего есть всегда и даром."},{"type":"p","text":"Вот образ, который помогает это увидеть. Сигарета — как сосед сверху, который сам же по ночам сверлит стену, а утром продаёт тебе беруши. Беруши работают, шум стихает, ты благодарен. И не замечаешь, что и сверло, и беруши — из одних рук. Уберёшь соседа — и сверлить станет некому. Тишина настанет сама, и платить за неё больше не придётся."},{"type":"h","text":"Почему отсюда всё-таки выходят"},{"type":"p","text":"Если дискомфорт между сигаретами создаёт сама привычка, то логика выхода становится понятной. Когда ты бросаешь, какое-то время яма ещё будет ощущаться — её же копали годами, она не засыпется за вечер. Первые дни обычно самые шумные: тяга накатывает, отпускает, накатывает снова. Но это не ровная стена, которую надо продавить волей. Это волны. И с каждым днём они становятся короче, реже и слабее — не по таймеру, у каждого свой ритм, но направление всегда одно. Тело перестаёт ждать дозу и заново привыкает жить в нуле, как когда-то умело."},{"type":"p","text":"На этих первых волнах необязательно стоять с голыми руками. Пластырь или жвачка с никотином, а по решению врача и таблетки — это не белый флаг и не признание, что ты слабее других. Это как держаться за поручень, пока вагон трясёт: помогает пройти качку, не геройствуя. Лучше всего такая опора работает не вместо понимания ловушки, а вместе с ним — когда ты видишь, что именно сглаживаешь и зачем."},{"type":"p","text":"А если вдруг сорвёшься и закуришь — это не крах и не повод махнуть рукой на всё. Считай это заметкой на полях: вот триггер, вот момент, где яму снова поманило. Одна затяжка не стирает неделю без сигарет. Счётчик в этом приложении помнит это за тебя — он не обнуляется от одного промаха."},{"type":"p","text":"А дальше мы разберём ещё одну подмену — то самое «удовольствие» от сигареты, которого, если честно присмотреться, никогда и не было."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"В следующий раз, когда потянет закурить, не доставай пачку сразу. Засеки минуту и тихо понаблюдай за ощущением: где именно в теле этот «голод», какой он на самом деле — острый или скорее мутный фон. Просто посмотри на него со стороны, как на чужого соседа со сверлом. Минута пройдёт — а вместе с ней ты увидишь, что это не ты слабый, это просто волна, и она уже идёт на спад."},{"type":"p","text":"Это образовательный текст и поддержка, а не медицинский совет. О пластыре, жвачке и тем более рецептурных таблетках стоит поговорить с врачом."}],
    takeawayRu: "Тяга — это не дыра в тебе. Это дыра, которую выкопала прошлая сигарета, чтобы продать тебе следующую.",
  },
  {
    id: "pleasure", number: 3, icon: "sparkle", color: "#FFD60A", readMin: 5, part: "I. Как работает ловушка",
    titleRu: "Удовольствие, которого не было",
    leadRu: "Кайф от сигареты — не вкус и не наслаждение, а выученная реакция на то, что наконец-то отпустило.",
    bodyRu: [{"type":"p","text":"В прошлой главе мы разобрали, как устроена сама ловушка: тяга появляется не просто так, у неё есть пружина, и эта пружина — никотин, который сам же создаёт дискомфорт, чтобы потом снять его. А теперь давай разберёмся с тем, что обычно кажется неприкосновенным. С удовольствием. С тем самым «ну мне же это нравится», на которое опирается любой курильщик, когда хочет оставить себе лазейку."},{"type":"p","text":"Потому что если честно посмотреть на это «нравится», от него мало что остаётся."},{"type":"h","text":"Мозг — плохой свидетель"},{"type":"p","text":"Представь: ты весь день за рулём в пробке, спина затекла, и наконец доезжаешь, выходишь и распрямляешься. Этот момент, когда хрустнуло и отпустило, — он приятный. Но ты же не думаешь, что научился любить разгибать спину как отдельное удовольствие. Просто до этого было плохо, а стало нормально, и контраст мозг пометил как «хорошо»."},{"type":"p","text":"С сигаретой ровно то же самое, только ты этого не видишь. Никотин уходит — поднимается лёгкое раздражение, рассеянность, пустота под рёбрами. Ты затягиваешься — и оно гаснет. Мозг ловит этот перепад «было неуютно → стало ровно» и ставит штамп: удовольствие. Хотя ты всего лишь вернулся в ту точку, где находится любой человек, который вообще не курит. В ноль. И платишь за этот ноль через каждый час-полтора, снова и снова."},{"type":"p","text":"Мозг — отличный сторож, но никудышный свидетель. Он не различает «мне хорошо» и «мне перестало быть плохо». Для него это одна и та же вспышка. И вся репутация сигареты как источника удовольствия держится ровно на этой путанице."},{"type":"h","text":"Тебе пришлось этому учиться"},{"type":"p","text":"Вспомни самую первую сигарету. Честно вспомни, без романтики. Горло обожгло, в голове поплыло, кого-то даже тошнило, и первая мысль была «и что, людям это правда нравится?». Никакого наслаждения. Организм встретил дым ровно как то, чем он и является, — как раздражающую гарь, от которой надо избавиться."},{"type":"p","text":"И вот что важно: вкус к сигаретам не пришёл сам. Ты его выработал. Затяжка за затяжкой ты приучал себя терпеть то, что поначалу было откровенно противно, — пока неприятное не стало привычным, а привычное мозг не записал в «приятное». Настоящее удовольствие так не работает. Тебе не нужно тренироваться, чтобы полюбить тёплый хлеб, прохладную воду в жару или запах после дождя. Они нравятся сразу. А тут — пришлось продираться через отвращение, чтобы добраться до «кайфа». Это не похоже на наслаждение. Это похоже на дрессировку."},{"type":"p","text":"То, к чему пришлось себя приучать через «фу», — стоит того, чтобы спросить: а кто кого тут приучил?"},{"type":"h","text":"Условный рефлекс, а не любовь"},{"type":"p","text":"Помнишь собаку, у которой при звонке начинала течь слюна? Потому что звонок раз за разом совпадал с едой. Сам по себе звонок никакой не вкусный. Просто мозг связал одно с другим так прочно, что тело реагирует на пустой сигнал."},{"type":"p","text":"У тебя то же самое, только сигналов целая связка. Сигарета склеилась с утренним кофе, с выходом на балкон, с паузой после тяжёлого разговора, с компанией друзей у подъезда. И когда наступает любой из этих моментов, ты чувствуешь «хочу закурить». Но хочешь ты не дым. Ты хочешь паузу. Тишину. Разрешение ничего не делать пять минут. Повод выйти из накалённой комнаты. Сигарета просто оказалась рядом в нужный миг и тихо записала всё это на свой счёт — будто это она дарит тебе кофе, балкон и тишину, хотя они были тут и до неё."},{"type":"p","text":"Это хорошая новость, между прочим. Кофе, балкон, пауза, друзья — всё это останется с тобой. Исчезнет только лишняя строчка в счёте, которую ты оплачивал зря."},{"type":"h","text":"Простая проверка"},{"type":"p","text":"В следующий раз, когда закуришь, не спеши. Поймай тот самый момент, который ты называешь приятным, и задай себе один тихий вопрос: что именно мне сейчас хорошо — от дыма во рту или оттого, что отпустило напряжение, которое было минуту назад?"},{"type":"p","text":"Прислушайся честно. Сам по себе горячий дым — он приятный на вкус? Или приятно совсем другое: что зуд внутри стих, что руки заняты, что ты разрешил себе выдохнуть и не быть ни для кого? Почти всегда, если присмотреться, окажется, что наслаждался ты не сигаретой. Ты наслаждался передышкой. А её можно взять и без неё."},{"type":"p","text":"И когда это однажды увидишь по-настоящему, изнутри, а не на словах, — бросить перестаёт ощущаться как отказ от удовольствия. Потому что отказываться не от чего: удовольствия, которое ты якобы теряешь, никогда и не было. Об этом ощущении потери — что будто бы у тебя что-то отбирают — мы поговорим в следующей главе. Там окажется, что и она устроена хитрее, чем кажется."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"А теперь — не вопрос, а маленькое действие. Возьми и проживи ближайшую передышку без сигареты. Когда в следующий раз потянет выйти и закурить — всё равно выйди. Встань на балкон, у окна, во двор. Те же пять минут, та же тишина, тот же повод ни для кого не быть. Просто без дыма. И заметь, что почти всё, ради чего ты выходил, осталось на месте. Тридцать секунд тишины — и одно тихое наблюдение, никому не отчитываться."}],
    takeawayRu: "Ты не бросаешь удовольствие. Ты увольняешь посредника, который продавал тебе твою же передышку.",
  },
  {
    id: "why-loss", number: 4, icon: "heart", color: "#FF6482", readMin: 5, part: "I. Как работает ловушка",
    titleRu: "Почему бросить кажется потерей",
    leadRu: "Тебе страшно не из-за никотина — страшно из-за того, что мозг считает сигарету частью тебя. Разберёмся, чья это на самом деле часть.",
    bodyRu: [{"type":"p","text":"Мы уже договорились, что удовольствия, ради которого ты якобы куришь, на самом деле не было — была просто пауза в дискомфорте, который сам же никотин и устроил. Но даже когда это понимаешь головой, внутри всё равно сидит что-то тяжёлое. Какая-то заранее заготовленная тоска. Будто впереди не свобода, а похороны."},{"type":"p","text":"Это и есть самое странное в отказе от курения. Логически ты ничего не теряешь — теряешь кашель по утрам, запах в куртке, деньги, одышку на третьем этаже. А ощущается так, словно у тебя забирают друга. Давай честно разберёмся, откуда берётся это чувство и кому оно принадлежит."},{"type":"h","text":"Мозг привязал сигарету к сотне мелочей"},{"type":"p","text":"За годы курения ты выкурил не «пачку в день». Ты выкурил конкретные моменты. Первая затяжка с кофе, пока чайник ещё булькает. Перекур после того, как закрыл сложную задачу. Сигарета, когда вышел из шумного помещения на улицу и наконец стало тихо. Затяжка в машине на светофоре. После еды. После ссоры. После секса. Перед важным звонком, чтобы собраться."},{"type":"p","text":"Мозг — машина по поиску связей. Он не разбирается, полезна привычка или нет, он просто замечает: вот это действие повторяется рядом вот с этим моментом — значит, склею их вместе. И склеил. Сотни раз. Поэтому теперь кофе без сигареты кажется недоделанным, а пауза без затяжки — пустой. Это не сигарета такая волшебная. Это ты сам, своими руками, привязал её к лучшим и важнейшим точкам своего дня."},{"type":"p","text":"Хорошая новость прячется ровно там же. Раз связи создал мозг, мозг их и распускает. Кофе останется кофе. Тишина после шумного дня останется тишиной. Момент после еды никуда не денется. Сигарета тут была не хозяином этих минут, а случайным соседом, который пристроился рядом и сделал вид, что без него никак."},{"type":"h","text":"Это не друг. Это надсмотрщик"},{"type":"p","text":"Друг — это тот, кто рядом, когда тебе хорошо, и не требует ничего взамен. Проверь сигарету по этому признаку. Она рядом, когда тебе хорошо? Или она приходит, когда становится плохо — и плохо становится ровно потому, что её давно не было? Друг не будит тебя ночью требованием выйти на балкон. Друг не портит отпускной перелёт. Друг не заставляет стоять под дождём у входа в кафе, пока остальные сидят в тепле."},{"type":"p","text":"То, что ты принимаешь за дружбу, — это привязанность заложника к тому, кто его держит. Тебе кажется, что сигарета тебя выручает, потому что она снимает напряжение, которое сама же и создала. Это как если бы коллега каждое утро прокалывал тебе шину, а потом подвозил на работу — и ты бы искренне считал его спасителем. Расстаться с таким — не потеря. Это конец смены, на которую ты не нанимался."},{"type":"h","text":"Страх говорит не твоим голосом"},{"type":"p","text":"Когда ты представляешь жизнь без сигарет и внутри всё сжимается — прислушайся, чей это голос. «А вдруг не справлюсь», «а как же кофе», «а вдруг я стану скучным и злым», «потом, не сейчас, сейчас неподходящий момент». Это очень убедительно. Но это не твоё мнение о себе. Это зависимость защищает свой источник питания, и говорит она ровно то, что заставит тебя оставить всё как есть."},{"type":"p","text":"Разница простая. Ты хочешь дышать полной грудью, не считать сигареты в пачке, не планировать день вокруг перекуров. Голос страха хочет одного — чтобы ты закурил снова. Как только научишься их различать, половина силы этого страха исчезает. Не потому что он врёт красиво, а потому что ты наконец видишь, кто говорит."},{"type":"p","text":"И да — первые дни правда будут плотнее. Тяга приходит не ровным фоном, а наскоками: поднимется, постоит немного и схлынет, как вода под ногами на берегу. Чем дальше, тем эти наскоки реже и тише. Если в какой-то момент накрывает особенно сильно, это не слабость характера и не повод стискивать зубы в одиночку. Иногда проще пройти это с опорой — кому-то помогает короткий разговор, кому-то прогулка, а кому-то и аптечные средства поддержки. Что именно из аптечного подойдёт и подойдёт ли вообще — это разговор с врачом, не с книгой и не с приложением. Смысл один: опора нужна не вместо тебя, а рядом, пока ты делаешь свою часть."},{"type":"h","text":"Не «бросаю» — «избавляюсь»"},{"type":"p","text":"Слова делают больше, чем кажется. «Бросаю» — это про лишение. Будто у тебя что-то отнимают, а ты стоишь и героически терпишь. С такой установкой каждый день — это борьба, и рано или поздно устаёшь бороться. «Избавляюсь» — совсем другая история. От чего избавляются? От того, что мешало, давило, надоело. От лишнего груза в рюкзаке на длинном подъёме."},{"type":"p","text":"Попробуй прожить эту разницу не как красивую фразу, а как факт. Ты не теряешь сигарету — ты возвращаешь себе кофе, тишину, паузу, утро без кашля и вечер без беготни за пачкой. Всё это было твоим с самого начала. Никто у тебя ничего не забирает — наоборот, со стола убирают того, кто годами сидел между тобой и твоей же жизнью."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Возьми одну привычную «сигаретную» сцену — например, кофе утром или выход на улицу после работы. Вслух или про себя скажи: «Это моё. Это останется со мной и без сигареты». Одна сцена, одна фраза, тридцать секунд. Ты не отнимаешь у себя момент — ты забираешь его обратно себе целиком."},{"type":"p","text":"Это образовательный текст, поддержка в отказе, а не медицинский совет. Любые аптечные средства и их применение — только после разговора с врачом."}],
    takeawayRu: "Ты не прощаешься с другом — ты выпроваживаешь незваного соседа, который годами выдавал твою же жизнь за своё гостеприимство.",
  },
  {
    id: "stress", number: 5, icon: "wind", color: "#5AC8FA", readMin: 4, part: "II. Разбор иллюзий",
    titleRu: "«Снимает стресс» — самая дорогая ложь",
    leadRu: "Сигарета не выключает стресс — она его создаёт, а потом берёт с тебя плату за короткую передышку.",
    bodyRu: [{"type":"p","text":"В прошлой главе мы говорили о том, что бросить кажется потерей — будто у тебя что-то отнимают. Теперь разберём, что именно ты якобы теряешь. Чаще всего звучит одно: «Но она же меня успокаивает». Это самый честный на вид аргумент. И самый дорогой обман."},{"type":"p","text":"Представь: ты на кухне, чайник свистит, ребёнок зовёт из комнаты, в мессенджере горит уведомление от начальника. Ты выходишь на балкон, закуриваешь — и плечи опускаются. Кажется, сигарета сняла напряжение. Но давай посмотрим медленнее, что там произошло на самом деле."},{"type":"h","text":"Кто на самом деле тревожнее"},{"type":"p","text":"Есть неудобный факт: по исследованиям, курящие в среднем тревожнее некурящих — не наоборот. Звучит против всего, что обещает сигарета, да? Если бы она правда успокаивала, курильщики были бы самыми безмятежными людьми на свете. А выходит ровно обратное."},{"type":"p","text":"И ещё одно, чего почти никто не ждёт: у многих людей через несколько недель после отказа тревожность не подскакивает, а наоборот — оседает. Фон становится ровнее. Человек, который годами был уверен, что курит «от нервов», вдруг замечает, что нервничать стал реже. Не потому что жизнь стала проще. А потому что из неё убрали один постоянный источник дёрганья."},{"type":"h","text":"Что ты принимаешь за спокойствие"},{"type":"p","text":"Вот в чём фокус. Никотин уходит из крови быстро. Через час-полтора после последней сигареты тело начинает тихо подныривать — лёгкое беспокойство, рассеянность, что-то скребёт. Ты этого почти не осознаёшь, просто становится чуть не по себе. И вот ты закуриваешь — и возвращаешься в норму. То ровное состояние, которое ты ощущаешь как «успокоился», — это не плюс. Это всего лишь возврат к нулю из небольшого минуса, в который тебя завело предыдущее курение."},{"type":"p","text":"Знаешь, как затекает рука, если долго спать на ней? Ты этого во сне не чувствуешь — а потом меняешь позу, кровь возвращается, и по руке расходится тепло, почти удовольствие. Только руке это «удовольствие» подарила не смена позы. Его создало само онемение, которое ты до этого терпел. Сигарета работает так же: сначала тихо пережимает тебе нерв отвыкания, потом на минуту отпускает — и выдаёт это облегчение за подарок."},{"type":"h","text":"Второй стресс поверх первого"},{"type":"p","text":"Настоящие стрессы никуда не делись. Дедлайн, ссора, безденежье, больной родитель — это реальная жизнь, и сигарета её не трогает. Зато она кладёт сверху ещё один слой. Каждые час-полтора тело само подкидывает тебе маленькую дозу беспокойства — и тебе приходится её гасить. Получается, к настоящим заботам ты добровольно доплачиваешь фоновую, искусственную, которой у некурящих просто нет."},{"type":"p","text":"А теперь представь день, когда сигарет нет под рукой. Совещание затянулось, в гостях нельзя выйти, рейс задержали. Заметь, что с тобой творится: ты не можешь думать ни о чём, кроме как добыть курево. Вот он, твой главный поставщик паники — не начальник и не пробка, а сама зависимость. Бросив, ты не лишаешься спокойствия. Ты снимаешь с себя обязанность каждые полтора часа спасаться от того, что само же тебя и накрывает."},{"type":"h","text":"Что успокаивает по-настоящему"},{"type":"p","text":"Раздражение проходит не от никотина, а от того, что ты делаешь вокруг сигареты, сам того не замечая. Ты выходишь из комнаты — меняешь обстановку. Останавливаешься — берёшь паузу между раздражителем и реакцией. И главное — делаешь медленный, длинный выдох. Тело читает такой выдох как сигнал «опасности нет» и сбрасывает обороты. Это не эзотерика, это простая физиология: на длинном выдохе пульс чуть замедляется."},{"type":"p","text":"Хорошая новость в том, что выдох, паузу и смену картинки можно оставить, а дым — выкинуть. Пройтись до окна и обратно, выйти на воздух без сигареты, потянуться, налить воды. Поначалу будет непривычно — рука помнит ритуал и тянется его повторить. Это нормально и проходит. А если первые дни даются тяжело, у тебя под рукой есть честные помощники для этих волн. Никотиновый пластырь или жвачка сглаживают самые резкие пики, а с врачом можно обсудить и рецептурные варианты. Тут нет ничего стыдного и ничего про слабость: это как взять зонт, когда знаешь, что польёт. Помощники не бросают за тебя — они держат тебя на ногах, пока новые привычки встают на место. И работают они в связке с этими привычками, а не вместо них."},{"type":"p","text":"Дальше мы разберём ещё одну знакомую отговорку — про то, что сигарета будто бы помогает сосредоточиться. Сценарий там окажется до смешного похожим."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Сделай один медленный выдох — длиннее вдоха. Вдох на счёт четыре, выдох на счёт восемь, губами как будто задуваешь свечу через всю комнату. Один раз, не торопясь. Заметь, что плечи чуть опустились сами — и без всякого дыма."},{"type":"p","text":"Это образовательный текст, а не медицинский совет. Любые препараты для отказа от курения, особенно рецептурные, обсуждай с врачом."}],
    takeawayRu: "Сигарета не гасит стресс — она его поджигает, а ты платишь ей за роль пожарного.",
  },
  {
    id: "focus", number: 6, icon: "target", color: "#0A84FF", readMin: 5, part: "II. Разбор иллюзий",
    titleRu: "«Помогает сосредоточиться»",
    leadRu: "Сигарета не возвращает тебе ясность — она же её и забрала.",
    bodyRu: [{"type":"p","text":"Со стрессом мы уже разобрались. Но есть ещё одна вещь, которую сигарета якобы делает — и в неё веришь даже когда всё остальное уже под сомнением. Будто без неё голова не работает. Будто именно затяжка собирает мысли в кучу. Это, пожалуй, самая хитрая иллюзия, потому что она прикидывается не удовольствием, а пользой."},{"type":"h","text":"Туман, который приходит сам"},{"type":"p","text":"Смотри, как это выглядит изнутри. Ты сидишь над задачей — отчёт, код, разговор, который надо обдумать. Проходит час, может полтора, и мысли начинают расплываться. Строчки скользят мимо, ты перечитываешь абзац третий раз и не понимаешь, о чём он. Внутри нарастает мутное «не могу больше думать»."},{"type":"p","text":"Ты выходишь, закуриваешь — и через минуту в голове проясняется. Можно работать дальше. Вывод напрашивается сам собой: сигарета вернула концентрацию. Логично же — было плохо, покурил, стало хорошо."},{"type":"p","text":"Только причина перепутана со следствием. Этот туман — не усталость мозга от работы, она бывает у всех и приходит позже. Это лёгкое никотиновое отвыкание, которое накапливается между сигаретами. Тело привыкло к веществу, и когда его уровень падает, появляется та самая рассеянность, раздражение, ощущение «не соображаю». У некурящего человека именно такого провала — резкого, на ровном месте, посреди дня — просто нет. Ему нечему проваливаться: никто внутри не дёргает рубильник."},{"type":"h","text":"Затяжка убирает то, что сама и принесла"},{"type":"p","text":"Получается замкнутый круг. Сигарета напускает туман — спустя время после прошлой. Следующая затяжка туман разгоняет. И ты записываешь это разгоняние себе в плюс, как будто получил что-то ценное. А на деле просто вернулся в обычное состояние, в котором некурящий находится по умолчанию, бесплатно, без всякого ритуала у подъезда."},{"type":"p","text":"Это как если бы кто-то незаметно подкручивал тебе яркость на экране в минус, а потом подходил и за деньги возвращал её обратно. Ты благодарен за свет. Но свет у тебя и так был — пока этот кто-то не вмешался. Сигарета не даёт тебе фокус. Она его сначала забирает, а потом отдаёт кусочками, по одной затяжке за раз, и берёт за это твоё здоровье и твоё время."},{"type":"h","text":"А как же все остальные"},{"type":"p","text":"Если бы концентрация правда зависела от никотина, мир был бы устроен иначе. Хирург не смог бы вести операцию на пять часов — посреди разреза ему бы потребовался перекур. Пилот на длинном рейсе не дотянул бы до посадки с ясной головой. Диспетчер, который держит в уме два десятка бортов, давно бы всё перепутал."},{"type":"p","text":"Но они работают. Сосредоточенно, годами, на задачах, где цена ошибки несравнима с твоим отчётом. Некурящий студент сдаёт сессию. Некурящий шахматист просчитывает партию на десять ходов вперёд. Никакого тайного источника фокуса, которого ты лишён, у них нет. Просто их внимание не подламывается каждые час-два — потому что его некому подламывать."},{"type":"p","text":"Ты и сам это знаешь по себе. Когда ты увлечён чем-то по-настоящему — фильмом, игрой, разговором с близким человеком — ты не вскакиваешь курить. Можешь забыть про сигареты на пару часов и не заметить. Значит, способность концентрироваться у тебя есть, своя. Она никуда не делась — просто её то и дело перебивали."},{"type":"h","text":"Что будет, когда бросишь"},{"type":"p","text":"Честно: первые дни голова может быть и правда тяжеловатой. Туман, который раньше ты разгонял затяжкой, теперь какое-то время висит дольше. Это сбивает с толку — кажется, вот же, без сигарет я хуже соображаю. Но это не новое состояние, это старый долг, который тело отдаёт. Дальше волны такой рассеянности становятся короче, реже и слабее, и счёт идёт не на часы по таблице, а на дни и недели — у каждого по-своему."},{"type":"p","text":"А потом, как правило, происходит спокойная и приятная штука. Ты ловишь себя на том, что просидел над задачей час, два — и тебя не тянуло прерваться. Фокус идёт без тех самых провалов и без подзарядки. Это и есть то внимание, которое всегда было твоим, просто ему годами не давали поработать в полную силу."},{"type":"p","text":"И ещё — пауза тебе по-прежнему будет нужна. Мозг действительно устаёт и просит передышки время от времени, это нормально. Только передышка — это про то, чтобы встать, размяться, посмотреть в окно, выпить воды. Не про дым. Дым тут был самозванцем: выдавал обычную потребность в паузе за потребность в сигарете."},{"type":"p","text":"А если захочешь опереться на что-то ещё — пластырь, жвачку, рецептурное средство от врача — это не белый флаг и не признак, что ты слабее других. Скорее перила на лестнице: держишься, пока ступеньки самые крутые, а потом отпускаешь. Лучше всего такие вещи работают рядом с тем, что ты делаешь прямо сейчас — разбираешь иллюзию по косточкам, а не глушишь её одной таблеткой."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"В следующий раз, когда поймаешь себя на мысли «надо покурить, чтобы собраться» — засеки две минуты. Не кури, просто встань, отойди от экрана, сделай десять медленных вдохов и посмотри куда-нибудь вдаль, в окно или в конец комнаты. А потом вернись к задаче и понаблюдай: голова прояснилась? Если да — это работа паузы, а не дыма. Запомни это ощущение."},{"type":"p","text":"И сразу оговорюсь: это книга, а не назначение. Что и когда подключать из аптечного — решай с врачом, он знает твою историю, а страница — нет."}],
    takeawayRu: "Сигарета не включает твой фокус — она его сначала гасит, а потом продаёт обратно по затяжке.",
  },
  {
    id: "reward", number: 7, icon: "gift", color: "#FF9F0A", readMin: 5, part: "II. Разбор иллюзий",
    titleRu: "«Награда» и «расслабление»",
    leadRu: "Сигарета не возвращает покой — она возвращает беспокойство, которое сама же и создала. Разбираемся, как перестать «заслуживать» то, что тебя обкрадывает.",
    bodyRu: [{"type":"p","text":"Мы только что говорили о том, как сигарета будто бы помогает собраться с мыслями. А теперь — про обратную сторону того же дня. Не про работу, а про паузу после неё. Про тот самый момент, когда ты выдыхаешь и думаешь: «Всё, заслужил»."},{"type":"p","text":"Закрыл задачу, домыл посуду, довёз детей, дожал тяжёлый разговор — и рука сама тянется к пачке. Это ощущается как маленькая медаль самому себе. Как точка в конце предложения. И именно поэтому связку «награда» разобрать сложнее всего: она прикидывается чем-то добрым к тебе. Давай посмотрим, что там внутри на самом деле."},{"type":"h","text":"«Я заслужил» — а что именно ты получаешь?"},{"type":"p","text":"Тут работает простой механизм — мы про него уже говорили. Никотин уходит из крови за пару часов, и тело начинает тихо ныть: верни. Это лёгкое нытьё ты весь день принимал за усталость, за «тяжёлый день», за характер. А вечерняя затяжка просто на двадцать минут выключает нытьё — и ты называешь это наградой."},{"type":"p","text":"Представь, что весь день ты ходил в куртке, у которой молния зажата на полсантиметра — не расстёгнуть, не вдохнуть полной грудью. Привык, перестал замечать, списал на тесноту. А вечером молнию наконец расстегнули — и какое облегчение! Только облегчение это не от подарка. Просто прекратили то, что весь день мешало дышать. С сигаретой ровно так же: тебе вернули кусочек спокойствия, который до курения был у тебя всегда и бесплатно. Это не премия. Это возврат украденного, по которому ты ещё и благодаришь."},{"type":"p","text":"Самое обидное — настоящая твоя работа, твоё реальное усилие, тут вообще ни при чём. Дело сделал ты. А медаль почему-то вручает пачка. И с каждым разом ты всё крепче веришь, что без неё точка в конце дня не ставится."},{"type":"h","text":"Награда и отдых были до сигарет — и никуда не делись"},{"type":"p","text":"Вспомни, как отдыхает человек, который не курит вообще. Он закончил дело — и просто закончил. Сел, выдохнул, налил чаю, потупил в окно, погладил кота, написал другу глупость. Ему не нужен отдельный ритуал, чтобы «разрешить себе» паузу. Пауза и так его."},{"type":"p","text":"Расслабление — это не вещество, которое надо вдохнуть. Это состояние тела, когда с него сняли нагрузку. Горячий душ после смены. Тишина в машине, когда заглушил мотор и минуту просто сидишь. Первый глоток воды, когда долго не пил. Никотин ничего из этого не умеет — он умеет только заткнуть собственную ломку и выдать это за блаженство. Уберёшь его из картинки — и душ, тишина, вода никуда не денутся. Останется чистый отдых, без вшитого внутрь беспокойства, которое погонит тебя за следующей дозой через час."},{"type":"p","text":"Первые дни без сигарет момент награды будет ощущаться непривычно пустым — рука помнит маршрут. Это нормально и это проходит: тяга приходит и откатывает, как прибой, и с каждым днём волны короче и слабее. Не по расписанию, не «ровно через трое суток отпустит» — а постепенно. Ты не теряешь награду. Ты учишься получать её напрямую, без посредника, который берёт комиссию твоим здоровьем."},{"type":"h","text":"Разорвать связку «сделал дело → сигарета»"},{"type":"p","text":"Связка эта не врождённая — ты её натренировал. Сотни вечеров подряд: финал дела и затяжка приходили вместе, и мозг их склеил. Теперь любое «уф, закончил» автоматически достаёт пачку. Хорошая новость: то, что натренировано, перетренировывается. Связку не нужно перерезать силой воли в один присест — её нужно медленно переучить, подставляя на место дыма что-то другое."},{"type":"p","text":"Чем заменить сам момент? Не «ничем» — пустота слишком похожа на ту, которую раньше заполняла сигарета. Заменяй конкретным маленьким действием, у которого есть начало и конец, как у перекура. Закрыл рабочий день — выйди на балкон и просто постой две минуты, глядя на улицу, без телефона. Домыл посуду — налей себе чего-нибудь вкусного и выпей стоя у окна. Дожал тяжёлый разговор — поставь один трек, который любишь, и дослушай до конца, ничего больше не делая."},{"type":"p","text":"Смысл не в том, чтобы найти «замену сигарете один в один» — такой нет и не надо. Смысл — вернуть себе саму идею паузы как награды, отдельно от никотина. Через пару недель мозг привыкнет, что точку в конце дела ставит балкон, чай или трек, а не дым."},{"type":"p","text":"А если где-то сорвёшься — это не крах и не «всё насмарку». Считай это подсказкой: вот именно этот момент пока ещё накрепко зашит на сигарету, здесь шов крепче, чем тебе казалось. Заметил, запомнил, пошёл дальше — один промах не перечёркивает весь путь, он просто показывает, где доучиться. И если решишь добавить опору посерьёзнее — никотиновую жвачку или то, что выпишет врач, — это не белый флаг. Это как взять напарника на тяжёлый подъём: он не тащит за тебя, но идти заметно легче. Рецептурное — конечно, через врача."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Вспомни своё ближайшее «дело», которое сегодня закончишь, — посуду, работу, дорогу домой. Прямо сейчас реши заранее, чем наградишь себя вместо затяжки: один любимый трек, две минуты у окна или горячий чай стоя. Просто назови это вслух одной фразой — «закончу и поставлю такую-то песню». Всё. Ты только что начал переучивать связку."}],
    takeawayRu: "Дело сделал ты — тебе и награда. Сигарета лишь подсовывает счёт за покой, который и так был твой.",
  },
  {
    id: "company", number: 8, icon: "group", color: "#64D2FF", readMin: 4, part: "II. Разбор иллюзий",
    titleRu: "Скука, компания и повод",
    leadRu: "Почему сигарета не наполняет паузу, а уносит её — и как стоять рядом с курящими, оставаясь свободным.",
    bodyRu: [{"type":"p","text":"Есть привычки, где сигарета встроена в действие — кофе, руки, привычный жест. А есть кое-что потоньше: сигарета встраивается в пустоту. В паузу между делами, в неловкое молчание на остановке, в тот момент, когда вроде и заняться нечем, и уходить рано."},{"type":"h","text":"Пауза, которую у тебя забрали"},{"type":"p","text":"Смотри, как это устроено. Ты стоишь на балконе, ждёшь, пока закипит чайник. Пять свободных минут. И мозг подсказывает: покури, чтобы не пропадали. Кажется, что сигарета эти пять минут наполняет. Но попробуй вспомнить честно — что ты делал в эти минуты? Ты не отдыхал. Ты обслуживал сигарету: достал, прикурил, затянулся, стряхнул, потушил. Пауза была. Сигарета её не подарила — она в неё просто залезла и заняла собой всё место."},{"type":"p","text":"Это как попутчик в купе, который всю дорогу говорит без умолку. Тишина и так была твоей — ты ехал, смотрел в окно. Но он занял собой каждую минуту, и теперь кажется, будто без него и дороги бы не было. Сигарета не создаёт паузу. Она её отбирает и продаёт обратно, выдавая за свою."},{"type":"p","text":"Настоящая пауза — это когда ты просто стоишь и смотришь во двор. Дышишь. Ничего не делаешь, и это нормально. Раньше тебе было неловко ничего не делать, и сигарета закрывала эту неловкость. Теперь неловкость пройдёт сама — за несколько дней мозг переучивается, что пустые минуты не нужно ничем затыкать. Первое время будет тянуть. Потом эти моменты станут просто твоими."},{"type":"h","text":"Что на самом деле ценно в компании"},{"type":"p","text":"Перекур с коллегами или с друзьями во дворе — это ведь не про дым. Это про то, что вы вышли, отошли от дел, поговорили. Про пять минут вне рабочего чата. Про «ну что, как сам?». Дым тут — случайный попутчик, а не суть. Но он так долго стоял рядом с этими хорошими минутами, что ты начал их путать."},{"type":"p","text":"Проверь сам. Самые тёплые разговоры на перекуре — они были из-за сигареты или вопреки ей? Ты запомнил, как друг рассказал что-то важное — или как ты в этот момент затягивался? Общение — твоё. Воздух — твой. Сосед по двору, который тебя выслушал, никуда не денется, если ты выйдешь без пачки. А вот дым в этих сценах был лишним всегда — просто ты привык не замечать."},{"type":"p","text":"Можно выходить с курящими и не курить. Можно держать в руке стакан чая вместо сигареты. Можно стоять, болтать, дышать прохладным воздухом — и быть полноценным участником, а не выпавшим. Компания собирается ради людей, а не ради пачки на двоих."},{"type":"h","text":"Как стоять рядом с курящими и быть свободным"},{"type":"p","text":"Тебе будут предлагать. Будет дым под носом. Будет тот самый момент, когда все достали, а ты нет, и пальцы вспомнят. Это не испытание силы воли — это просто старая дорожка в голове, которая ещё не заросла. Тут помогает не стискивать зубы, а сменить роль. Ты не «тот, кто героически терпит». Ты просто человек, который вышел поговорить и больше не курит. Спокойно, без объявления, без борьбы."},{"type":"p","text":"Если кто-то протягивает пачку — «спасибо, я уже не». Без лекций, без «а ты знаешь, что...». Чем меньше драмы, тем легче. Драму создаёт мысль, что ты чего-то лишён. Но лишён не ты. Лишён тот, кто стоит и кашляет, отойдя от компании на ветер, потому что не может просто постоять с людьми без этого."},{"type":"p","text":"А если на каком-то поводе — день рождения, баня, шашлыки, пара бокалов — рука сама потянулась и ты затянулся, это не крушение. Это одна затяжка, которая показала тебе твой триггер, вот где тебя качает. Это данные, не приговор — про это будет отдельный разговор дальше. Главное сейчас: один промах не отменяет недели без дыма, и счётчик в приложении не обнулится. Ты не вернулся в начало — ты узнал про себя что-то полезное и идёшь дальше."},{"type":"h","text":"Скука — это не повод закурить"},{"type":"p","text":"«Скучно, дай покурю» — самая странная сделка из всех. Скуке нужно хоть что-то: посмотреть в окно, позвонить кому-то, размяться, выпить воды, выйти пройтись. Сигарета на скуку отвечает не действием, а дымом, от которого тяжелеет голова и портится дыхание. Это всё равно что от голода грызть упаковку, а не еду внутри."},{"type":"p","text":"Скука — нормальное человеческое состояние. Иногда нечем заняться, и это не катастрофа, которую надо срочно гасить. Если хочется чем-то занять руки и голову — займи. Но честно: то, что ты выбираешь от скуки, должно тебе хоть что-то давать. Сигарета не даёт. Она берёт — минуты, дыхание, деньги — и оставляет тебе только повод закурить снова."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Вспомни одно место, где ты курил «от скуки» или «за компанию» — балкон, двор, курилка у работы. Прямо сейчас мысленно постой там 30 секунд без сигареты: что ты видишь, слышишь, чем пахнет воздух. Эта пауза была твоей и без дыма. Завтра, оказавшись там, просто побудь в ней — подыши и иди дальше."}],
    takeawayRu: "Сигарета не наполняет пустую минуту — она в неё вселяется и берёт с тебя плату за постой.",
  },
  {
    id: "ritual", number: 9, icon: "coffee", color: "#C2773F", readMin: 4, part: "II. Разбор иллюзий",
    titleRu: "Руки, кофе, ритуал",
    leadRu: "Половина сигарет в твоей жизни — это не про никотин, а про сценарий, который легко переписать.",
    bodyRu: [{"type":"p","text":"Есть сигареты, которые ты как будто и не выбираешь. Налил кофе — потянулся за пачкой. Доел обед — встал и вышел. Сел за руль — щёлкнул зажигалкой раньше, чем поворотником. Рука знает дорогу лучше тебя. И вот это ощущение — «я даже не успел подумать» — пугает сильнее всего. Кажется, что внутри сидит что-то химическое и неуправляемое."},{"type":"p","text":"Хорошая новость: это не химия. Это привычка. А привычку видно насквозь, если знать, куда смотреть."},{"type":"h","text":"Кофе ничего не требует. Требует сценарий"},{"type":"p","text":"Никотин не знает, что ты пьёшь кофе. Ему всё равно, обед у тебя или совещание, балкон или остановка. У него нет глаз. Связь «кофе — сигарета» построил не он, а ты — сотнями повторений. Каждое утро ты ставил эти два действия рядом, и мозг сделал вывод, который делает всегда: раз идут вместе — значит, одно вызывает другое. Так склеиваются кофе и затяжка, еда и перекур, телефонный звонок и пачка в руке."},{"type":"p","text":"Представь, что полгода подряд ты заедал каждую чашку кофе одной долькой шоколадки. Через полгода кофе без шоколадки покажется неполным — будто чего-то не хватает. Но это же не значит, что в кофе живёт тяга к шоколаду. Это просто пара, которую ты сам и собрал. С сигаретой ровно так же. Тебе не плохо без неё — тебе непривычно. А это совсем другое чувство, хоть и маскируется под первое."},{"type":"h","text":"Ассоциации рассыпаются быстрее, чем кажется"},{"type":"p","text":"И вот тут самое обнадёживающее. Связку держит только повторение. Перестал подкармливать — она начинает таять. Первые несколько раз будет ощутимо: выпил кофе, а руки не пристроены, и внутри зудит «где?». Но если ты в этот момент не закуриваешь, мозг получает новый опыт: кофе был, сигареты не было, и ничего страшного не случилось. Отметь это про себя — вот тебе и доказательство, что пара разъединяется."},{"type":"p","text":"Через несколько повторений тот же кофе уже не дёргает за рукав так настойчиво. Потом ещё тише. Здесь важно не перепутать две разные вещи. Бытовые сцепки — это не та тяжёлая волна, что накрывает в первые дни без сигарет и потом сходит на нет. Ритуальная привычка устроена куда проще: ей не нужно ждать, пока перестроится тело. Ей нужно всего лишь пару раз увидеть, что сценарий теперь идёт без сигареты, — и она отпускает. Поэтому такие сцепки распадаются за дни, иногда за пару недель, а не за месяцы."},{"type":"p","text":"А если ты однажды закуришь на кофе — это не «всё насмарку». Это просто значит, что вот эта конкретная сцепка ещё живая, и её стоит расцепить отдельно. Один такой раз — это галочка на твоей карте триггеров: ага, утренний кофе пока цепляет сильнее остальных. Не приговор, а подсказка, куда смотреть завтра. Счётчик в Бризе из-за одной сигареты не обнулится — и тебе себя обнулять незачем."},{"type":"h","text":"Займи руки и рот — и перепиши сцену"},{"type":"p","text":"Бросать через героическое терпение — плохая стратегия. Сидеть, сжав кулаки, и смотреть на дымящую чашку кофе как на врага — так надолго не хватит. Гораздо умнее не терпеть пустоту, а заполнить её. У ритуала две физические части: чем заняты руки и что во рту. Их и закрывай."},{"type":"p","text":"Руки любят мелкое и вращательное: покрути ручку, пощёлкай степлером, перебери ключи, разомни кусочек пластилина у клавиатуры, наведи порядок в одном ящике. Рту нужно движение и вкус: вода с лимоном мелкими глотками, зубочистка с мятой, семечки, долька яблока, жвачка без сахара, леденец. Звучит мелко, но именно эта мелочь и держала сигарету в твоей руке — значит, мелочью её и заменишь."},{"type":"p","text":"И главный приём — поменяй саму сцену, а не вырезай из неё кусок. Не «кофе минус сигарета» (дырка, в которую тянет), а «кофе плюс что-то новое». Пей его не на привычном балконе, а у окна на кухне. Возьми другую кружку. Включи пару минут музыки. После обеда не выходи на старое место для перекура, а пройдись вокруг дома. Ты не борешься со старым сценарием — ты пишешь поверх него новый, и старому просто не остаётся места в кадре."},{"type":"p","text":"Кстати, бывает, что врач подобрал тебе НЗТ или другой препарат. Тогда он работает как звукоизоляция в комнате, где постоянно гудела дрель: фоновый шум стихает, и за новые сцены садишься в тишине, а не пытаясь перекричать тягу. Это не замена твоей работе с привычками, а её соседка по столу. И уж точно не белый флаг — скорее наоборот, человек выбрал инструмент потолковее."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Прямо сейчас налей себе воды или того же кофе и выпей пару глотков, держа кружку обеими руками. Просто почувствуй: руки заняты, во рту вкус, ничего не горит — и тебе при этом нормально. Вот так будет выглядеть твоё новое утро."},{"type":"p","text":"Это образовательный текст и поддержка, а не медицинский совет. Любые препараты — рецептурные, и решение о них принимаешь с врачом."}],
    takeawayRu: "Тебе не плохо без сигареты — тебе непривычно. А непривычное становится привычным быстрее, чем ты думаешь.",
  },
  {
    id: "too-long", number: 10, icon: "tree", color: "#34C759", readMin: 4, part: "II. Разбор иллюзий",
    titleRu: "«Я слишком долго курю»",
    leadRu: "Стаж — это не приговор. Тело умеет чиниться в любом возрасте, а «жалко бросать после стольких лет» — самая хитрая ловушка из всех.",
    bodyRu: [{"type":"p","text":"Есть мысль, которая приходит не у пепельницы, а где-то глубже. Не «хочу курить», а «мне уже поздно». Ты держал чашку кофе, крутил в пальцах пачку, ловил себя на ритуале — и вдруг тихо решил, что всё это уже не отлепить. Слишком много лет. Слишком въелось. Эта глава — про то, что «поздно» врёт."},{"type":"p","text":"Давай разберём это спокойно, без лозунгов. Потому что за «я слишком долго курю» прячутся две разные вещи, и обе разваливаются, если на них посмотреть."},{"type":"h","text":"Тело не считает твой стаж"},{"type":"p","text":"Внутри тебя нет бухгалтера, который записал двадцать лет курения и теперь отказывается возвращать здоровье, пока не выйдет срок. Тело устроено проще и добрее: оно начинает чиниться от последней сигареты, а не от первой. Ему всё равно, сколько было до. Ему важно только одно — есть дым сейчас или нет."},{"type":"p","text":"Представь старую квартиру, где годами курили на кухне. Жёлтый потолок, запах в шторах, налёт на окне. Кажется — всё, пропиталось навсегда. А потом кто-то открывает форточку, моет окно, стирает занавески. И через пару недель уже не верится, что тут было так. Стены те же. Квартира та же. Просто перестали добавлять копоть — и она начала уходить сама."},{"type":"p","text":"С телом так же, только живее. Кровь у многих уже в первые дни начинает носить больше кислорода — раньше его подъедал угарный газ из дыма, а теперь он уходит. Дальше потихоньку легче даётся лестница, дольше держится вкус еды, ровнее дыхание во сне. Не потому что ты герой — а потому что ты просто перестал подливать. И крошечные реснички в лёгких, которые годами лежали придавленные, понемногу поднимаются и снова работают. Это не красивые слова, это обычная физиология, и ей нет дела до того, тебе сорок или шестьдесят пять."},{"type":"h","text":"Ловушка «жалко всё бросать»"},{"type":"p","text":"А вот вторая мысль хитрее. «Я столько лет вкладывал — деньги, время, привычку. Бросить сейчас — как будто признать, что всё было зря». И ты словно доплачиваешь сигаретами за прошлые сигареты, лишь бы они не оказались ошибкой."},{"type":"p","text":"Это знакомая ловушка, и она работает не только с куревом. Купил билет в кино, через двадцать минут понял — фильм скучный. Но сидишь до конца. Зачем? «Деньги же заплачены». Хотя деньги уже ушли в любом случае — а ты вдобавок отдаёшь два часа жизни, чтобы не признавать, что билет был так себе. Уйти было бы умнее. Остаться — это платить дважды."},{"type":"p","text":"С курением то же самое, только ставка выше. Прошлые годы потрачены — это правда, и её не отменить ни одной выкуренной сигаретой. Но каждая новая пачка не возвращает прошлое, а отбирает будущее. Ты не «добираешь», ты просто кладёшь сверху ещё. Длинный стаж — не причина продолжать. Это самый громкий аргумент остановиться: ты и так уже отдал достаточно."},{"type":"h","text":"Прошлое закрыто, будущее — нет"},{"type":"p","text":"Тут важно быть честным. Бросить — не значит обнулить. Прошлое не сотрётся, и обещать тебе «станешь как некурящий» было бы враньём. Но будущее устроено иначе, чем прошлое: оно ещё не написано. И каждый день без дыма — это не возврат долга, это уже прибыль. Сегодняшний вечер, который ты прожил спокойнее. Деньги, которые не сгорели. Утро без той тяжести в груди."},{"type":"p","text":"Считай не назад, а вперёд. Назад — там только то, что уже случилось, его трогать бессмысленно. Вперёд — там всё открыто. Первый день окупается тем же первым днём: тело уже начало работать на тебя, а не против. Не нужно ждать год, чтобы «стало стоить того». Оно стоит того с первого выдоха."},{"type":"p","text":"И если впереди будет трудно — а первые дни обычно труднее остальных, — это не значит, что для тебя «уже всё решено» и стаж заранее всё проиграл. Никакой долгий срок не делает тебя особенным случаем, которому поздно. Споткнёшься — это будет просто спотыкание, один эпизод, а не приговор на все прожитые годы. Стаж не судья. Он остался позади, а решаешь ты здесь."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Прямо сейчас, за полминуты: положи ладонь на грудь и сделай один спокойный вдох — не глубокий, не показательный, просто внимательный. Почувствуй, как поднимается и опускается грудная клетка под рукой. Это твоё тело дышит само, без сигареты, ровно так же, как дышало в детстве, до первой затяжки. Оно умеет это и сейчас — стаж тут ни при чём. Начать можно с любого вдоха. И самый подходящий — вот этот."}],
    takeawayRu: "Тело чинится с последней сигареты, а не с первой. Длинный стаж — не долг, который надо доплачивать, а счёт, который пора закрыть.",
  },
  {
    id: "withdrawal", number: 11, icon: "wave2", color: "#FF453A", readMin: 5, part: "III. Тело и страхи",
    titleRu: "Правда о ломке",
    leadRu: "Честный разговор о том, как на самом деле проходит отвыкание — без страшилок и без вранья.",
    bodyRu: [{"type":"p","text":"Ты уже знаешь: дело не в том, сколько лет за плечами. Стаж — это не приговор, это просто цифра. А теперь давай про то, чего боятся почти все, кто откладывает первый день. Про ломку."},{"type":"p","text":"Вокруг неё накручено столько, что страшно даже подходить. Будто бросить — это спуститься в подвал, где тебя ждёт что-то невыносимое. Давай включим там свет и посмотрим, что на самом деле в углу. Чаще всего — швабра и старый велосипед."},{"type":"h","text":"Она реальная — но не та, что в кино"},{"type":"p","text":"Сразу честно: отвыкание существует. Тело привыкло получать никотин по расписанию, и когда расписание ломается, оно ворчит. Это не выдумка и не «всё в голове». Лёгкая раздражительность, рассеянность, желание что-то жевать, сбитый сон, ощущение, что чего-то не хватает в руках — всё это бывает."},{"type":"p","text":"Но в голове у многих сидит совсем другая картинка — из фильмов про тяжёлые наркотики. Трясущиеся руки, холодный пот, человек на полу. Так вот: никотин — не из той лиги. Сравни сам. Для большинства бросить — это примерно как первый день без утреннего кофе у заядлого кофемана. Голова чуть тупит, настроение качается, тянет к привычному. Неприятно — да. Невыносимо — нет."},{"type":"p","text":"У кого-то проходит мягче, у кого-то жёстче — тут всё индивидуально, и это нормально. Если вдруг накрывает сильно или долго, особенно если давит на сон или на настроение, это не значит, что с тобой что-то не так. Это значит, что стоит не геройствовать в одиночку, а опереться на инструменты или поговорить с врачом. Просить поддержки — не слабость, а здравый смысл."},{"type":"p","text":"А ещё важно прочувствовать вот что: страх перед ломкой обычно куда сильнее самой ломки. Ты заранее рисуешь себе ад, а приходишь — а там сквозняк и скрипучая дверь."},{"type":"h","text":"Громче в начале, дальше — волнами"},{"type":"p","text":"Не буду врать про точные часы и сутки — мол, к такому-то моменту попустит, как по будильнику. У всех по-разному, и тело — не таймер. Но общая форма у всех похожая."},{"type":"p","text":"Первые дни — самые шумные. Тело громче всего напоминает о привычке, потому что разрыв ещё свежий. А дальше включается то, что стоит запомнить: тяга идёт волнами. Она не висит над тобой ровным гулом сутки напролёт. Она накатывает — и откатывает. Поднялась, постояла на гребне минуту-другую — и опала."},{"type":"p","text":"И с каждым днём эти волны становятся короче, реже и слабее. Представь прибой после шторма: сначала бьёт сильно и часто, потом всё спокойнее, и вот уже просто рябь у берега. Процесс идёт не часами — днями и неделями. Но идёт в одну сторону. Вниз."},{"type":"h","text":"Болит не тело — болит мысль"},{"type":"p","text":"А теперь главное наблюдение, ради которого всё это. Когда накрывает тяга, кажется, что мучается тело. Соматика, конечно, есть — но львиная доля шума всё-таки в мыслях. Не зудит кожа, не ломит кости. Свербит идея: «сейчас бы». Одна навязчивая мысль, которая крутится и обещает, что станет легче, стоит только закурить."},{"type":"p","text":"Поймай это различие — оно меняет всё. Чаще всего тебе не больно. Тебе настойчиво думается про сигарету. А мысль, в отличие от боли, можно просто переждать. Она не может заставить твою руку двигаться. Она только громко предлагает."},{"type":"p","text":"И вот тут многие совершают ошибку: сжимают зубы и терпят. Держатся из последних сил, как будто волна — это враг, которого надо передавить. Но чем сильнее упираешься, тем тяжелее. Есть способ умнее."},{"type":"h","text":"Оседлай волну, а не дерись с ней"},{"type":"p","text":"Сёрфер не пытается остановить волну — это невозможно и глупо. Он встаёт на доску и скользит по ней, пока она сама не выдохнется. С тягой так же."},{"type":"p","text":"Когда накатывает, не борись. Заметь её. Скажи себе спокойно: «О, привет. Тяга пришла. Сейчас поднимется, постоит и спадёт». Понаблюдай со стороны, будто за погодой за окном. Где она в теле? В груди, в горле, в руках? Просто посмотри, без паники. И дыши. Волна доходит до пика — и начинает опадать сама, без твоих усилий. Тебе нужно только не спрыгнуть с доски в эти минуты."},{"type":"p","text":"Это и есть скольжение по тяге. Не «перетерпеть на зубах», а проводить волну взглядом до берега. С каждым разом получается легче — ты уже знаешь, что она пройдёт, потому что прошлая прошла."},{"type":"p","text":"И ещё. Бывает, волны бьют так, что одной доски мало — и в этом нет ничего постыдного. Тут на твоей стороне пластыри, жвачки, рецептурные препараты. Это не белый флаг и не подпорка для тех, кто «не справился сам». Скорее тёплая куртка, когда вода ледяная: она не делает тебя хуже пловцом, она просто даёт продержаться в воде дольше и не околеть. И работают они не вместо того, что ты сейчас осваиваешь, а рядом с ним, плечом к плечу. Что именно из рецептурного тебе подойдёт — это разговор с врачом, не со мной и не с приложением."},{"type":"p","text":"А если волна всё-таки накрыла с головой и ты закурил — это не провал и не «всё пропало». Это просто строчка в твоих наблюдениях: вот такая волна, вот такой момент пока оказались сильнее. Один раз — это один раз, а не разворот к старой жизни. И Бриз тут на твоей стороне: счётчики не обнуляются, к нулю тебя никто не отбрасывает. Ты просто узнал про свои волны чуть больше, чем знал вчера."},{"type":"p","text":"Кстати, пока тело учится жить без никотина, оно одновременно начинает чиниться — и довольно быстро. Но об этом дальше: про то, что именно и в каком порядке восстанавливается."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Вспомни последнюю сильную тягу. А теперь засеки минуту и подыши: вдох на четыре счёта, медленный выдох на шесть. Просто наблюдай, как воздух заходит и выходит. Это твоя тренировочная доска — на спокойной воде, пока волны нет. Когда придёт настоящая, ты уже будешь знать движение."},{"type":"p","text":"Это образовательный текст, а не медицинский совет. НЗТ (пластырь, жвачка) продаётся без рецепта; цитизин, бупропион и варениклин — только по назначению врача."}],
    takeawayRu: "Тяга — это волна, а не стена: на стену лезут, по волне скользят.",
  },
  {
    id: "body-heals", number: 12, icon: "lung", color: "#30D158", readMin: 4, part: "III. Тело и страхи",
    titleRu: "Что чинится в теле",
    leadRu: "Тело начинает чинить себя само — где-то за дни, где-то за годы. Вот честная карта без волшебных часов.",
    bodyRu: [{"type":"p","text":"В прошлой главе мы разобрали, что волны тяги — это не приговор, а просто погода, которая меняется. Теперь давай о хорошем. Пока ты переживаешь эти волны, в теле уже идёт ремонт. Тихий, без фанфар, но настоящий."},{"type":"p","text":"Только сразу договоримся об одном. В интернете гуляют красивые таблички: «через 20 минут — то, через 8 часов — сё, через 12 часов — пятое». Выглядит вдохновляюще, но половина этих цифр — маркетинг, а не биология. Тело — не микроволновка с таймером. Оно чинится не по расписанию, а по своему темпу, и темп этот у каждого свой. Поэтому давай без секундомера — просто по-честному, что и примерно когда."},{"type":"h","text":"Первые недели: возвращается то, что ты почти забыл"},{"type":"p","text":"Самое заметное приходит быстро — это дыхание, вкус и запах. Курильщик годами живёт с приглушёнными чувствами, как будто кто-то накинул на мир тонкое одеяло: всё на месте, но глуше, чем должно быть. А потом одеяло снимают."},{"type":"p","text":"Знакомая многим история: человек бросает, проходит неделя-полторы, он заходит в подъезд и вдруг чувствует, чем пахнет лестничная клетка. Чужой ужин из-за двери. Сырость в углу. Кофе, который кто-то варит этажом выше. Запахи были там всегда, просто ты их не ловил. То же с едой. Обычный помидор из магазина вдруг оказывается помидором, а не красным водянистым ничем. Чёрный хлеб начинает по-настоящему пахнуть хлебом."},{"type":"p","text":"Дыхание тоже меняется рано. Не то чтобы ты внезапно побежишь марафон — но подняться на четвёртый этаж и не остановиться на площадке отдышаться становится как-то проще, чем раньше. Мелочь, а замечаешь."},{"type":"h","text":"Месяцы: лёгкие наводят порядок"},{"type":"p","text":"А вот кашель и одышка — это уже не про недели. Тут наберись терпения, потому что бывает обидно. Многие ждут, что бросишь — и дышать станет легче сразу. А по факту первое время можно начать кашлять даже сильнее. И люди пугаются: «я же бросил, почему хуже?»"},{"type":"p","text":"Объясню по-простому. В лёгких есть крошечные реснички — что-то вроде эскалатора, который выносит наверх всякую дрянь. Дым этот эскалатор парализует, и весь мусор годами копился внизу. Бросаешь — эскалатор оживает и начинает разгребать завал. Кашель в эти недели — это не поломка, это уборка. Тело выносит то, что давно пора было вынести. Месяц-другой — и становится тише. Одышка отступает на той же дистанции: не за выходные, а постепенно, шаг за шагом, через недели и месяцы."},{"type":"p","text":"Тут важно не перепутать. Если кашель не уходит долго, странный по характеру или с кровью — это не «ремонт», это повод показаться врачу, а не сидеть и гадать. Приложение тебе тут не советчик. Здоровье лёгких проверяет человек в халате, а не статья."},{"type":"h","text":"Месяцы и годы: сердце играет вдолгую"},{"type":"p","text":"Сердце и сосуды чинятся медленнее всего — и это, наверное, самая важная новость, хотя самая незаметная. Ты её не почувствуешь так, как запах кофе. Тут нечего нюхать и не на что обращать внимание изо дня в день. Просто где-то внутри, на дистанции месяцев и лет, риски, которые курение накручивало годами, потихоньку откатываются назад."},{"type":"p","text":"Представь это как кредит, который ты выплачиваешь. Каждый день без сигарет — небольшой платёж по долгу, который тело копило. Сразу ничего не видно. Но через год расклад другой, чем был. Через несколько лет — ещё другой. Это та работа, которая не даёт фидбэка прямо сейчас, и именно поэтому про неё легко забыть. Но она идёт, даже когда ты её не замечаешь."},{"type":"h","text":"Почему «чувствую» бьёт «знаю»"},{"type":"p","text":"И вот тут самое интересное про мотивацию. Цифры про сосуды и проценты риска — это про голову. Они правильные, но холодные. А вот то, что ты сам почувствовал, — это совсем другая весовая категория."},{"type":"p","text":"Одно дело прочитать «улучшается дыхательная функция». Другое — самому заметить, что ты пробежал за автобусом полквартала и не сложился пополам у остановки. Одно дело знать, что вернётся вкус. Другое — откусить мандарин в декабре и поймать себя на мысли «о, а он сладкий». Вот это «о» работает сильнее любой таблички. Тело само подкидывает тебе доказательства, что ты не зря держишься. Лови их и складывай в копилку — в трудный вечер они весят больше, чем любая статистика."},{"type":"p","text":"А страхи про вес, нервы и «я теперь буду другим человеком» — это отдельный разговор, и он в следующей главе. Там тоже всё не так страшно, как кажется на старте."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Сделай один медленный вдох через нос — глубокий, до самого живота — и просто прислушайся: чем пахнет там, где ты сейчас? Найди один запах, который раньше проходил мимо тебя. Это и есть ремонт в действии, прямо в эту минуту."},{"type":"p","text":"И последнее, по-честному: это рассказ о том, как восстановление идёт у большинства, а не обещание лично тебе. У каждого тела свой темп и свои нюансы, так что за личной картиной — к врачу, а не к этим строчкам."}],
    takeawayRu: "Тело чинит себя не по таймеру из интернета, а по-своему: что-то за недели, что-то за годы. Твоя работа — просто не мешать и замечать.",
  },
  {
    id: "fears", number: 13, icon: "shield", color: "#5AC8FA", readMin: 5, part: "III. Тело и страхи",
    titleRu: "Вес, нервы и другие страхи",
    leadRu: "Разбираем то, чего боятся почти все бросающие, — и смотрим, как страх теряет силу, когда видишь, как он устроен.",
    bodyRu: [{"type":"p","text":"Ты уже знаешь, что тело начинает чинить себя само, без твоих усилий. Но рядом с этой хорошей новостью почти всегда стоит маленький список страхов. Они приходят ещё до того, как ты потушил последнюю сигарету, и шепчут на ухо. Давай вытащим их по одному на свет и разберём каждый — потому что страх держится, пока остаётся смутным силуэтом, и тает, как только видишь его в подробностях."},{"type":"p","text":"Заметь одну вещь: почти все эти страхи не про сегодня. Они про какого-то будущего тебя, которого ещё нет. «А вдруг я растолстею», «а вдруг стану психом». Воображаемая беда всегда выглядит крупнее реальной — потому что в воображении нет ни деталей, ни выхода, только голый ужас крупным планом."},{"type":"h","text":"Страх первый: «я расплывусь»"},{"type":"p","text":"Честно, без приукрашивания: часть людей действительно набирает пару-тройку килограммов в первые месяцы. Не все. Не обязательно. И точно не «плюс размер навсегда». Цифра, которую обычно называют, — где-то два-четыре килограмма; у кого-то побольше, у кого-то вовсе ничего. Если у тебя прибавилось чуть больше среднего — это не значит, что что-то пошло не так. Это не приговор, а то, чем можно управлять."},{"type":"p","text":"Откуда вообще берётся вес. Сигарета слегка глушила аппетит и чуть разгоняла обмен — копеечная подачка за большой счёт. Когда она уходит, еда снова становится вкусной, а руки ищут, чем себя занять. И вот ты у холодильника не потому, что голоден, а потому что в три часа дня раньше была сигарета, а теперь — пустота, которую проще всего заткнуть печеньем."},{"type":"p","text":"Видишь механизм — видишь и ручку громкости. Это не голод, это привычка руки и рта искать ритуал. Стакан воды, прогулка до окна, горсть орехов вместо пачки печенья. Тело, которое перестало платить за дым кислородом, через пару недель само захочет двигаться — и весы это заметят. Вес тут не враг, а просто ещё один процесс, у которого есть причина. А с причиной всегда можно договориться."},{"type":"h","text":"Страх второй: «я превращусь в злого психа»"},{"type":"p","text":"Первые дни ты правда можешь быть колючим. Огрызнулся на близкого из-за ерунды, дёргаешься в очереди, кажется, что весь мир сговорился тебя бесить. И тут включается коварная мысль: «вот он я настоящий, без сигарет — невыносимый человек»."},{"type":"p","text":"Это неправда, и вот почему. Раздражительность в эти дни — не твой характер, который вылез наружу. Это отвыкание. Мозг привык получать дозу каждый час и теперь капризничает, как ребёнок, у которого забрали соску. Капризничает громко, но недолго. Первые дни тяжелее, дальше волны идут короче, реже и слабее — не по расписанию, а просто сходят на нет, через дни и недели."},{"type":"p","text":"Сравни с простудой. Когда тебя ломает и течёт из носа, ты же не думаешь «вот теперь я навсегда такой больной». Ты знаешь: это пройдёт, это временное состояние, а не новая версия тебя. С раздражительностью ровно так же. Через неё не нужно становиться кем-то — через неё нужно просто пройти. Если же дело не в колючести, а в том, что настроение держится подавленным и не отпускает неделями, — это уже повод спокойно показаться врачу, а не терпеть в одиночку."},{"type":"p","text":"А ещё эти дни можно сделать мягче — и тут есть чем себя поддержать. Пластырь или никотиновая жвачка снимают часть напряжения, а кому-то по рецепту врача подойдут и таблетки. Это не белый флаг и не признак того, что ты слабее других. Это как взять зонт, когда заранее знаешь, что будет дождь: не «не справился сам», а просто разумно. Работает такая поддержка лучше всего рядом с твоим решением, а не вместо него."},{"type":"h","text":"Страх третий: «я стану скучным»"},{"type":"p","text":"А вот этот страх — самый хитрый, потому что он притворяется твоим собственным голосом. «Без сигареты я не расслаблюсь по-настоящему», «посиделки с друзьями станут пресными», «как же кофе утром без неё». Звучит как твоё личное мнение. На самом деле это говорит зависимость — тем единственным способом, которым она умеет удерживать: пугая, что без неё будет хуже."},{"type":"p","text":"Поймай её на нестыковке. Сигарета не добавляла в кофе вкуса, а в разговор — смысла. Она просто на минуту снимала ломку, которую сама же и завела час назад. То, что ты принимал за «кайф расслабления», было всего лишь облегчением оттого, что зависимость на время отстала. Это как чесать комариный укус: приятно ровно потому, что до этого невыносимо зудело. Убери комара — и чесать будет нечего, и руки свободны."},{"type":"p","text":"Скучным человека делает не отсутствие дыма, а скука внутри. Тот, кто умел смеяться с друзьями, не разучится этому без пачки в кармане. Наоборот — без постоянных перекуров-побегов на балкон ты будешь там, где всё и происходит, целиком."},{"type":"h","text":"Почему страхи тают"},{"type":"p","text":"Заметил общее? Каждый из этих страхов держался на одном и том же — на незнании, что там внутри. «Растолстею» — пока не увидел, что вес это просто рука, ищущая занятие. «Стану злым» — пока не понял, что это отвыкание, а не характер. «Стану скучным» — пока не разглядел, что это не твой голос, а голос ловушки. У каждого страха под капотом оказался обычный, понятный механизм. А с механизмом уже можно что-то делать — в отличие от безымянного «а вдруг»."},{"type":"p","text":"И ещё одно, чтобы держать в голове наперёд: если где-то на пути ты оступишься — это не перечёркивает всё, что было. Одна сигарета не отматывает тебя в начало, она просто показывает, какой именно момент тебя подловил. Считай это подсказкой, а не приговором. Но об этом — в следующей главе, отдельно и подробно."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Возьми один свой страх — тот, что громче всех. Скажи его вслух или напиши одной строкой, а следом допиши: «а на самом деле это…» и закончи механизмом, а не ужасом. Например: «боюсь потолстеть — а на самом деле это просто рука ищет, чем заняться вместо сигареты». Одна минута. Названный по имени страх сразу становится меньше."},{"type":"p","text":"Это книга-поддержка, а не медицинский совет: про препараты и любые тревожные симптомы решай вместе с врачом, рецептурное — только через него."}],
    takeawayRu: "Страх — это туман. Включаешь свет, видишь механизм — и пугаться становится нечем.",
  },
  {
    id: "lapse", number: 14, icon: "feather", color: "#64D2FF", readMin: 5, part: "IV. Срыв и опора",
    titleRu: "Ты не провалился",
    leadRu: "Одна выкуренная сигарета — это не конец пути, а строчка данных о том, где у тебя слабое место.",
    bodyRu: [{"type":"p","text":"Страх набрать вес, страх остаться без привычного успокоения — со всем этим мы уже разобрались. Но есть ещё один страх, который держит крепче всех: страх, что ты опять сорвёшься. И вот ты держишься неделю, две, а потом на чьём-то дне рождения берёшь одну — «за компанию». И всё. Внутри будто что-то обрывается: «Ну вот, опять не смог»."},{"type":"p","text":"Давай остановимся прямо здесь. Потому что в эту секунду решается главное — и решаешь ты, а не сигарета."},{"type":"h","text":"«Сто раз бросал» — это сто раз опыта"},{"type":"p","text":"Есть такая народная отговорка: «Бросить курить легко, я сам бросал сто раз». Её обычно роняют с горькой усмешкой — мол, какой я безнадёжный. А теперь переверни её. Сто попыток — это сто раз, когда ты уже видел, как именно тебя цепляет."},{"type":"p","text":"Каждый прошлый срыв оставил тебе подсказку. Один раз сорвался в первый же вечер пятницы, когда открыл пиво. Другой — когда поссорился с женой и вышел на балкон остыть. Третий — на рабочем созвоне, который тянулся два часа. Это не список твоих позоров. Это карта. Карта мест, где дорога проседает, и где в следующий раз нужно ступать осторожнее."},{"type":"p","text":"Человек, который бросает в первый раз, идёт вслепую. Ты — нет. У тебя за плечами разведка боем. Обидно только, что эту разведку обычно списывают в графу «я неудачник», вместо того чтобы пользоваться ей как картой."},{"type":"h","text":"Ловушка одной мысли"},{"type":"p","text":"Самое опасное в срыве — не сама сигарета. Опасна мысль, которая приходит сразу за ней: «Ну всё, программа сломана, я опять курю». Вот эта мысль и есть настоящий обрыв. Назовём её по-простому — эффект нарушенного зарока: ты сам себе дал слово, сам его нарушил и тут же решил, что раз уж нарушил — то можно и до конца."},{"type":"p","text":"Представь: ты сел на диету, а вечером не удержался и съел одну конфету. Если думаешь «день испорчен, доедаю всю коробку, с понедельника заново» — ты съешь коробку. Хотя по-честному ущерб от одной конфеты — это одна конфета. Всё остальное доедает не голод, а вот эта мысль «всё пропало»."},{"type":"p","text":"С сигаретой ровно так же. Одна затяжка на дне рождения — это одна затяжка. Никотина в крови от неё мизер, через сутки его не останется. Но если за ней идёт «раз закурил — значит снова курю», то ты докуриваешь не из-за никотина. Ты докуриваешь из-за приговора, который сам себе вынес. Промах превращается в запой не химией, а одной фразой в голове."},{"type":"p","text":"Поэтому в Бризе твой счётчик не обнуляется от одной сигареты. Это не поблажка и не подыгрывание. Это правда: один промах не стирает недели, что ты уже прошёл. Стирает их только решение «начать с нуля» — а ты не обязан его принимать."},{"type":"h","text":"Промах и возврат — разные вещи"},{"type":"p","text":"Важно развести два слова, которые путают постоянно. Промах — это одна сигарета, один вечер, одна слабая минута. Возврат — это когда ты снова куришь каждый день, как раньше. Между ними нет автоматического моста. Этот мост ты достраиваешь сам — каждой следующей сигаретой после первой. Или не достраиваешь."},{"type":"p","text":"Между первой затяжкой и пачкой назавтра есть зазор. В этом зазоре ты решаешь: «это была случайность, дальше не курю» — и мост рушится, не успев появиться. Или «ну раз пошло такое дело» — и кладёшь первую доску. Никотин в этом выборе не участвует. Участвуешь только ты."},{"type":"p","text":"А если решишь подключить препарат — пластырь из аптеки или то, что выписал тебе врач, — выкинь из головы, что это белый флаг. Скорее это вторая пара рук: пока ты держишь руль, кто-то рядом гасит самые резкие толчки тяги, и зазор, в котором ты успеваешь подумать, становится чуть шире. Работает это не вместо твоей головы, а заодно с ней — и лучше всего как раз тогда, когда ты уже раскусил, как устроена ловушка."},{"type":"h","text":"Что делать прямо после промаха"},{"type":"p","text":"Алгоритм простой, и он умещается в три шага. Первый — признать без драмы. Не «я ничтожество», а сухо, как механик о машине: «Окей, была сигарета». Точка. Никакого внутреннего суда, прокурора и адвоката — это и есть тот самый клей, который превращает один промах в десять."},{"type":"p","text":"Второй — посмотреть, что было за минуту до. Где ты был, с кем, что почувствовал? Скука, злость, рюмка, чужой дым под носом? Это и есть твой триггер — тот самый, с которым отдельно разберёмся в следующей главе. Сейчас важно просто его заметить и записать. Ты добавил ещё одну метку на свою карту."},{"type":"p","text":"Третий — вернуться сразу. Не «с понедельника», не «с нового месяца», не «доживу эту пачку и брошу». Сразу. Следующая сигарета, которую ты не выкурил, — это и есть твоё возвращение. Чем короче пауза между промахом и возвратом, тем меньше шансов, что мост вообще начнёт строиться."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Вспомни свой последний срыв — любой, хоть многолетней давности. И в одну строчку, без оценок, ответь себе: где ты был и что почувствовал прямо перед той сигаретой? Это займёт минуту — и у тебя на руках окажется первая отметка на твоей личной карте триггеров. Не приговор. Данные."},{"type":"p","text":"И короткая оговорка про препараты выше: это образовательный текст, а не медицинский совет. Что подключать и подключать ли вообще — решаешь не ты в одиночку и не приложение, а ты вместе с врачом."}],
    takeawayRu: "Срыв — это не «всё сначала». Это «вот здесь меня поджидали» — теперь ты знаешь маршрут.",
  },
  {
    id: "triggers", number: 15, icon: "compass", color: "#FF9500", readMin: 4, part: "IV. Срыв и опора",
    titleRu: "Триггеры и как их обезвредить",
    leadRu: "Тяга редко приходит из ниоткуда — у неё почти всегда есть спусковой крючок, и его можно вычислить заранее.",
    bodyRu: [{"type":"p","text":"Ты, наверное, уже заметил странную вещь. Иногда целое утро проходит — и ни одной мысли о сигарете. А потом одна планёрка, один звонок от мамы, одна пробка на Садовом — и рука сама тянется к карману. Тяга редко приходит просто так, по расписанию. У неё почти всегда есть спусковой крючок."},{"type":"p","text":"Этот крючок и называют триггером. Запах кофе. Пустая кухня в одиннадцать вечера. Голос начальника. Бокал вина в пятницу. Тело годами связывало эти моменты с затяжкой, и теперь оно честно достаёт привычку с полки, как только видит знакомую обстановку. Это не слабость характера. Это просто заученный маршрут — а маршруты можно перекладывать."},{"type":"h","text":"Четыре старых знакомых: голод, злость, одиночество, усталость"},{"type":"p","text":"Есть четыре состояния, на которых тяга паразитирует чаще всего. По-английски их собрали в слово HALT — «стоп»: Hungry, Angry, Lonely, Tired. Голодный, злой, одинокий, уставший. Удобно тем, что и звучит как команда: заметил одно из четырёх — остановись на секунду."},{"type":"p","text":"Голод подкрадывается незаметно. Ты не курить хочешь — ты есть хочешь, просто мозг перепутал сигналы, потому что раньше затяжка часто заменяла обед. Злость — самый горячий из четырёх: после ссоры кажется, что сигарета остудит. Не остудит. Она просто даст пять минут паузы, за которые можно было бы и так выйти на лестницу подышать. Одиночество — это вечер, когда все разошлись, и привычка предлагает себя в компаньоны. Усталость — конец дня, когда воли уже не осталось ни на что, и проще сдаться, чем сопротивляться."},{"type":"p","text":"Фокус в том, что почти всегда тебе нужно не курить. Тебе нужно поесть, остыть, кому-то позвонить или лечь спать. Сигарета просто громче всех кричит, что решит вопрос — а решает его еда, душ, сон или живой голос в трубке."},{"type":"h","text":"План «если — то», написанный заранее"},{"type":"p","text":"Самое слабое место — момент самой волны. В этот момент думать трудно, торговаться с собой бесполезно. Поэтому решение принимают не в бою, а до боя. Спокойно, на холодную голову, ты заранее раскладываешь: если случится вот это — я делаю вот то."},{"type":"p","text":"Звучит просто, и в этом вся сила. «Если выйду на перекур с коллегами — беру с собой стакан воды и просто стою рядом». «Если разозлюсь на работе — спускаюсь на улицу и три минуты иду быстрым шагом до угла и обратно». «Если останусь вечером один — ставлю чайник и пишу сестре, даже какую-нибудь ерунду». Заготовка работает, потому что в момент тяги тебе не нужно ничего изобретать. Решение уже лежит готовое, как зонт у двери."},{"type":"p","text":"Не пытайся накрыть всю жизнь сразу. Возьми два-три своих самых частых триггера — те, что повторяются каждый день, — и пропиши ответ только на них. Остальное добавишь по дороге, когда заметишь новые."},{"type":"h","text":"Если волна всё-таки накрыла"},{"type":"p","text":"Бывает, что план не сработал и тяга пришла во весь рост. Тогда вспомни главное, о чём мы подробно говорили в главе про ломку: тяга идёт волной. Она поднимается, доходит до гребня и опадает — сама, без сигареты, обычно за считаные минуты. Её не нужно давить и с ней не нужно воевать. По ней проще скользить: подыши, займи руки, посмотри в окно — и дай гребню пройти."},{"type":"p","text":"И чем дольше ты идёшь, тем добрее становятся эти волны. Первые дни — самые шумные, тут честно. Дальше они приходят реже, держатся короче и бьют слабее. Это вопрос дней и недель, а не марафона без конца. Тело перекладывает маршруты — просто ему нужно время."},{"type":"p","text":"А если на каком-то триггере ты всё-таки оступился — не спеши ставить на себе крест. Теперь ты точно знаешь, где у тебя тонко, и можешь дописать туда план. Что делать в первые минуты после такого момента, мы разбирали рядом — вернись к той главе, если нужно."},{"type":"h","text":"Готовиться заранее, а не в момент взрыва"},{"type":"p","text":"Главная мысль всей этой главы простая. С триггером гораздо легче справиться до того, как он сработал, чем в момент, когда он уже рвёт. Уставать до изнеможения — не обязательно: можно лечь раньше. Доводить себя до волчьего голода — незачем: можно держать в сумке орехи или яблоко. Копить злость весь день — не нужно: можно выпускать её прогулкой, а не дымом."},{"type":"p","text":"Ты не обязан справляться только силой воли в самый трудный момент. Если чувствуешь, что одних заготовок мало, есть вещи помощнее — то, что не отменяет твоих усилий, а подставляет под них плечо. О них поговорим дальше, отдельно и спокойно. Сейчас достаточно одного: начать видеть свои триггеры заранее и встречать их подготовленным."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Вспомни один момент, когда тебе чаще всего хочется закурить — самый предсказуемый, ежедневный. И прямо сейчас допиши к нему одну фразу: «Если [этот момент] — то я [конкретное действие на пару минут]». Например: «Если выйду из подъезда утром — то делаю три медленных вдоха и иду к остановке». Одна строчка. Этого хватит, чтобы завтра встретить триггер не с пустыми руками."}],
    takeawayRu: "Тягу не побеждают на пике волны — её разоружают накануне, пока ты ещё спокоен.",
  },
  {
    id: "tools", number: 16, icon: "pill", color: "#30D158", readMin: 4, part: "IV. Срыв и опора",
    titleRu: "Если решишь взять инструмент",
    leadRu: "Препарат — не белый флаг, а перчатка для горячей сковороды. Разбираемся, когда она в руку, а когда лишняя.",
    bodyRu: [{"type":"p","text":"Ты уже знаешь, как выглядит триггер в лицо — и что с ним можно сделать, не подкуривая. Дальше честный разговор, который многие откладывают из гордости. Про то, что у этого пути есть инструменты. И что взять их в руку — не значит расписаться в собственной слабости."},{"type":"h","text":"Перчатка, а не белый флаг"},{"type":"p","text":"Представь, что нужно снять с плиты раскалённую сковородку. Можно голой ладонью — терпеть, морщиться, обжечься. А можно взять прихватку. Никто не назовёт тебя слабаком за прихватку. Это просто разумно: меньше боли, тот же результат."},{"type":"p","text":"С никотином та же история. Когда ты бросаешь, тело какое-то время недоумевает и подаёт сигналы — раздражение, тяга, ощущение, что чего-то не хватает в руках и во рту. Первые дни обычно самые шумные. Потом это идёт волнами: накатило — отпустило, и с каждым разом волна короче и тише. Препарат не отменяет процесс. Он просто сглаживает пики, чтобы ты не принимал решений на голодный, дёрганый мозг."},{"type":"p","text":"Пластырь, жвачка, спрей — это никотин без дыма и без сотен попутных веществ из сигареты. Они мягко снижают фон, пока ты перестраиваешь привычки. Не поблажка для тех, кто послабее, и не признак, что ты сдался. Это та самая прихватка для горячей сковородки."},{"type":"h","text":"Инструмент работает в паре с тобой"},{"type":"p","text":"Тут есть ловушка, в которую легко угодить. Кажется: проглотил таблетку — и она сама всё сделает, а я посижу в сторонке. Так не выходит. Препарат снимает часть физического шума, но не учит тебя проживать вечер пятницы без сигареты, не разбирает твои триггеры, не отвечает на вопрос «а кто я теперь, без этого»."},{"type":"p","text":"Это как абонемент в зал. Карточка в кармане сама мышцы не растит. Но если ты ходишь — она открывает дверь, и заниматься становится проще. Инструмент и поведение работают вместе, а не вместо друг друга. Пластырь гасит тягу — а ты в это время осваиваешь новый способ пережить стресс, новый ритуал вместо перекура, новую версию себя на той же кухне."},{"type":"p","text":"И ещё. Если на этом пути случится промах — а он случается у многих — препарат тут ни при чём, и ты тоже не «всё перечеркнул». Один эпизод просто показывает, какой триггер оказался хитрее, чем ты думал. Бери его как подсказку на будущее, а не как приговор. Счётчик в приложении это понимает и не обнуляется. Оступиться разок и встать — совсем не то же самое, что вернуться к пачке."},{"type":"h","text":"Лестница, а не один прыжок"},{"type":"p","text":"Инструменты бывают разной силы, и их можно представить как ступени. Внизу — ты сам и твои новые привычки: дыхание, вода, прогулка, разобранные триггеры. Это база, и для многих её хватает."},{"type":"p","text":"Дальше идут средства помягче — те же пластыри и жвачки, что лежат в аптеке без рецепта. Ещё выше — препараты посерьёзнее: цитизин, бупропион, варениклин. Они действуют на сам механизм тяги изнутри и поэтому держат руку крепче. Но у крепкой хватки есть цена — у каждого свои показания, противопоказания и нюансы, в которых без специалиста не разобраться."},{"type":"p","text":"Поэтому простое правило: всё рецептурное — только через врача. Не через форум, не через «подруге помогло», не через это приложение. Доктор смотрит на тебя целиком — на твоё сердце, твою голову, твои другие лекарства — и решает, какой инструмент тебе по руке. А не подойдёт первый — пробуют следующий. Подбор бывает не с первого раза, и это нормально."},{"type":"p","text":"Но даже когда врач выписал рецепт, автор программы — ты. Ты решаешь, начинать ли с поведения или сразу взять подмогу. Ты замечаешь, помогает ли. Ты вместе с доктором двигаешься по ступеням вверх или вниз. Инструмент — в твоей руке, а не наоборот."},{"type":"p","text":"Так что не спеши примерять на себя ярлык. Не «я не смог без таблетки» — а «я выбрал пройти старт мягче». Это и есть твоя программа, собранная под тебя. А кем ты становишься, пока её собираешь — об этом дальше."},{"type":"p","text":"Это образовательный текст, а не медицинский совет. Любые рецептурные препараты — только по назначению врача."}],
    takeawayRu: "Инструмент держит руку — но идёшь ты сам. Молоток без столяра — это просто кусок железа на полу.",
  },
  {
    id: "identity", number: 17, icon: "crown", color: "#FFD60A", readMin: 5, part: "V. Свобода",
    titleRu: "Кем ты становишься",
    leadRu: "Бросить — это не про силу воли против сигарет. Это про то, кем ты себя считаешь.",
    bodyRu: [{"type":"p","text":"Есть два человека. Первый говорит: «Я пытаюсь бросить». Второй: «Я не курю». На словах разница — пара букв. На деле — две разные жизни."},{"type":"p","text":"«Пытаюсь бросить» — это всегда про борьбу, которая ещё идёт. Сигарета остаётся в кадре, просто теперь она запретная. Ты держишь её на дистанции вытянутой руки, и эта рука устаёт. А «я не курю» — это уже не про сигарету вообще. Это про тебя. Тут нечего удерживать, потому что и удерживать-то нечего."},{"type":"h","text":"Поведение идёт за тем, кем ты себя считаешь"},{"type":"p","text":"Представь знакомого, который принципиально не пьёт в будни. Не потому что лечится, не потому что дал зарок и теперь героически терпит. Просто он такой человек: рабочий вечер — значит, чай. Когда в пятницу коллеги зовут «по одной после планёрки», он не считает про себя до десяти и не вцепляется в край стола. Он говорит «я по будням не пью» и берёт морс. Без надрыва. Потому что «не пью в будни» — это не запрет, который он на себя повесил. Это просто он."},{"type":"p","text":"С сигаретами работает так же. Пока ты «на диете от курева», каждая пачка в магазине — испытание. Но когда курение перестаёт быть частью тебя, оно перестаёт и притягивать. Не потому что ты герой. А потому что это больше не твой вопрос. Чужие сигареты на столе — как чужой зонт в прихожей. Стоит и стоит, тебе-то что."},{"type":"p","text":"И вот тут важное. Ты не ждёшь, пока станешь некурящим, чтобы начать так думать. Ты начинаешь так думать — и становишься. Сначала фраза кажется чужой, как новая куртка с биркой. Поносишь неделю — и уже не замечаешь, что она на тебе."},{"type":"h","text":"Ты не воюешь — ты возвращаешься"},{"type":"p","text":"Бывает, что курение и правда хочется встретить в лоб: засечь момент, когда тянет, поймать привычку за руку. Это рабочий подход, и он своё место знает. Но как настроение, как то, чем живёшь день за днём, война выматывает. На войне всё время есть враг за рекой, окопы, и ты в напряжении: вдруг прорвётся. А сигарета — не армия. Это привычка, которую ты сам когда-то впустил, не зная, во что ввязываешься. Стоять против неё в окопах годами — устанешь раньше, чем она."},{"type":"p","text":"Куда легче дышится от другой картинки. Был ты — до первой затяжки. Любопытный подросток у подъезда, человек, который дышал полной грудью и не думал об этом. Этот ты никуда не делся. Его просто завалило сверху десятью годами автоматизма: рука к пачке, щелчок, затяжка, не глядя. Бросить — значит разгрести этот завал и вернуться к тому, кто был под ним. Ты не строишь нового человека с нуля. Ты откапываешь себя настоящего."},{"type":"p","text":"Поэтому это не лишение. Лишают того, у кого отбирают своё. А у тебя ничего не отбирают — наоборот, возвращают. Запах кофе по утрам. Способность пробежать за автобусом и не задохнуться. Вечер, который не нужно ставить на паузу ради лестничной площадки."},{"type":"h","text":"Что ты знаешь о себе — это не приговор"},{"type":"p","text":"В приложении ты увидишь цифры. Сколько ты куришь, в какие часы тянет сильнее, что было перед последней сигаретой — кофе, ссора, скука, дорога. Легко прочитать это как обвинительный акт: вот, мол, доказательство, насколько ты завис. Но это не про стыд. Это карта."},{"type":"p","text":"Зависимость — не дефект характера и не слабина. Это то, как никотин цепляется за нервную систему у всех подряд, у академиков и у дальнобойщиков одинаково. Знать, что у тебя самый трудный момент — это первая сигарета с утренним кофе, не унизительно. Это полезно ровно так же, как знать, что без восьми часов сна ты к обеду никакой. Данные о себе — это рычаг, а не клеймо. Чем точнее видишь свой механизм, тем меньше он управляет тобой втихую."},{"type":"h","text":"Один промах не делает тебя прежним"},{"type":"p","text":"Допустим, на одиннадцатый день ты затянулся. На свадьбе друга, под общий гул, кто-то сунул — и ты взял. Внутри тут же поднимается знакомый голос: «Ну всё, сорвался, опять курильщик, начинай заново». Вот это и есть самая опасная фраза в этой главе."},{"type":"p","text":"Одна затяжка не отменяет того, кем ты стал. Она показывает обстановку, в которой тебя качает, — и только. Курильщик возвращается, когда ты сам решаешь: «раз оступился — значит, всё зря, какой из меня некурящий». Между одной сигаретой и пачкой в день — целая пропасть, и кто её переходит, решаешь ты, а не сигарета. Поэтому одиннадцать дней без курения остаются одиннадцатью днями. Их у тебя никто не отнимает — даже ты сам. (Подробнее про срывы — в отдельной главе; здесь важно одно: промах не переписывает то, кем ты успел стать.)"},{"type":"p","text":"Тот, кто оступился и пошёл дальше, и тот, кто бросил без единого срыва, приходят в одно и то же место. Просто первый знает про себя чуть больше."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Скажи вслух, тихо, одну фразу: «Я некурящий». Не «я бросаю», не «я пытаюсь» — именно так. Послушай, как это звучит у тебя в голове. Если отозвалось странно и непривычно — это нормально, новая куртка всегда жмёт в плечах первые дни. Повтори завтра утром. И послезавтра."}],
    takeawayRu: "Ты не бросаешь курить. Ты перестаёшь быть тем, кто курил, — и оказывается, под этим всё время был ты.",
  },
  {
    id: "last-cig", number: 18, icon: "noSmoke", color: "#FF453A", readMin: 4, part: "V. Свобода",
    titleRu: "Последняя сигарета",
    leadRu: "Почему последняя сигарета — это не финальная битва, а просто тихая точка, после которой становится легче.",
    bodyRu: [{"type":"p","text":"Есть один образ, который тебе, скорее всего, подсунули заранее. Будто бросить — это встать на ринг и отбиваться. Сжать зубы, держаться из последних сил, считать дни, как заключённый царапает чёрточки на стене камеры. И где-то на горизонте маячит враг, с которым ты теперь будешь драться годами."},{"type":"p","text":"Это красивая история. Только она неправда. И, что важнее, она тебе мешает."},{"type":"h","text":"Боя не будет"},{"type":"p","text":"Никотин ведёт себя не как тюремщик, а как заевшая дверца, которая тихо скрипит, пока ты её не толкнёшь. Каждая сигарета чуть-чуть успокаивает раздражение, которое сама же и создала пару часов назад. Ты думаешь, что куришь, чтобы расслабиться. На деле ты просто ненадолго гасишь лёгкое неудобство, которого без сигарет вообще бы не возникло."},{"type":"p","text":"Поэтому, когда ты бросаешь, никакого великого сражения не происходит. Просто скрип постепенно стихает. Не сразу — первые дни дверца ещё подаёт голос. Но с каждым днём звуков меньше, они короче и тише. Это не битва длиной в годы. Это процесс длиной в дни и недели, и он идёт волнами: накатило — отпустило, накатило послабее — отпустило быстрее."},{"type":"p","text":"Сравни это не с войной, а с тем, как сходит загар после лета. Сначала кожа тёмная и заметная. Потом ты как-то перестаёшь обращать внимание. А через пару недель ловишь себя на том, что уже и не помнишь, какой была. Никто не называет это «героической борьбой с загаром». Просто тело идёт своим чередом, а ты ему не мешаешь."},{"type":"h","text":"Что такое последняя сигарета на самом деле"},{"type":"p","text":"Раз нет боя — нет и драмы вокруг «последней». Тебе могли продать ритуал: торжественно докурить, может, заснять на видео, сказать прощальную речь, раздавить окурок ногой как символ. В этом столько пафоса, что становится только тяжелее. Ведь чем больше церемоний, тем важнее кажется то, с чем прощаешься. А ты, по сути, прощаешься всего лишь с привычкой, которая годами тянула из тебя по чуть-чуть и ничего не давала взамен."},{"type":"p","text":"Последняя сигарета — это не финальный аккорд и не подвиг. Это просто точка. Та, после которой ловушка начинает разжимать пальцы. Не «я сделал невозможное», а «всё, я больше не плачу этот странный налог». Представь, что годами по ошибке оплачивал чужую подписку — списывалось каждый месяц, а ты толком и не пользовался. И вот наконец отменил. Ты же не устраиваешь по этому поводу прощальный вечер с цветами. Ты просто выдыхаешь: ну наконец-то."},{"type":"p","text":"Именно с таким настроением её и стоит встретить. Не «я её уничтожаю», а «спасибо, дальше я сам». Лёгкое облегчение вместо натуги. Если внутри вместо тяжёлой торжественности — спокойное «фух», значит, ты понял всё правильно. Дотлела, погасла, и ладно."},{"type":"h","text":"Первые часы по ту сторону"},{"type":"p","text":"Что чувствуешь сразу после? Скорее всего — странную тишину. Привычка подсовывала тебе десятки маленьких поводов: вышел из подъезда — закурил, допил кофе — закурил, нервничаешь перед звонком — закурил. И вот эти поводы приходят, а действия за ними нет. Рука тянется в карман и возвращается пустой. Это не боль. Это непривычка. Как когда переставил мебель и неделю поворачиваешь не туда, заходя в комнату."},{"type":"p","text":"В эти часы может накатить волна — короткое, настойчивое «хочу». Не пугайся её и не раздувай. У волны, как и у настоящей, есть гребень и спад: поднимется, постоит секунд тридцать на пике и сама пойдёт вниз, обычно за пару минут. Переждал — схлынула. А если в какой-то момент всё же закуришь — это не крах и не «теперь всё зря». Считай это меткой на карте: вот здесь, в этом месте, тебя качнуло сильнее всего, теперь ты знаешь, где постелить соломки. Одна осечка не перечёркивает пройденного, и счётчик в приложении из-за неё не вернётся к нулю."},{"type":"p","text":"И ещё. Если ты решил пройти этот участок не на голых руках — с пластырем, жвачкой или тем, что подобрал вместе с врачом, — здесь нечего стыдиться. Это не белый флаг, а просто способ приглушить лишний гул в голове, чтобы спокойнее разбираться с привычкой. Такая поддержка не делает работу за тебя — она расчищает стол, чтобы работать было легче. Голову всё равно ведёшь ты сам, просто без лишнего шума под ухом."},{"type":"p","text":"А дальше начинается то, ради чего всё затевалось: ты постепенно перестаёшь думать о сигаретах вообще. Но это уже разговор для следующих страниц — про того, кем ты становишься, и про то, как выглядит жизнь, когда дверца давно перестала скрипеть и ты про неё попросту забыл."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Не вставая с места, опусти плечи и дай телу на пару секунд обмякнуть — будто снял тяжёлый рюкзак. Ничего не поджигаешь, ничего не вдыхаешь, а внутри само собой становится чуть тише. Запомни это ощущение: оно теперь всегда при тебе, и для него не нужна пачка в кармане."},{"type":"p","text":"Это образовательный текст и поддержка, а не медицинский совет. Любые препараты — пластырь, жвачку, рецептурное — подбирай и обсуждай с врачом."}],
    takeawayRu: "Последняя сигарета — не финальный бой, а тихий момент, когда ловушка наконец разжимает пальцы. Её встречают не речью, а выдохом.",
  },
  {
    id: "freedom-life", number: 19, icon: "dove", color: "#34C759", readMin: 5, part: "V. Свобода",
    titleRu: "Жизнь по ту сторону",
    leadRu: "Свобода — это не финиш с лентой и медалью. Это вторник, в который ты просто живёшь.",
    bodyRu: [{"type":"p","text":"Последняя сигарета уже позади. Ты её докурил — или не докурил, неважно. Важно, что та сторона, о которой раньше думалось как о чём-то далёком и героическом, оказалась просто… твоей обычной жизнью. Без салютов. И вот про неё, про эту обычную жизнь, стоит сказать отдельно — потому что её редко описывают, а зря."},{"type":"h","text":"Утро, которое больше не начинается с кашля"},{"type":"p","text":"Раньше первое, что делало твоё тело по утрам, — прокашливалось. Будто проверяло, всё ли на месте после ночи. Ты привык к этому звуку настолько, что перестал его слышать. У многих со временем это уходит само: просыпаешься — и тихо. Грудь не тянет вниз, в горле не сидит этот привычный комок, который раньше казался частью тебя. Не у всех в один и тот же день и не по расписанию — но однажды ты ловишь эту тишину и удивляешься, что она твоя."},{"type":"p","text":"И запахи. Заходишь домой с улицы — и чувствуешь, что в квартире пахнет утренним кофе, а не вчерашней пепельницей. Берёшь со спинки стула любимую толстовку — она пахнет порошком, а не дымом. Целуешь ребёнка перед садиком — и он не морщится. Эти вещи маленькие, их не выложишь в сторис. Но именно из них и собрана новая нормальность."},{"type":"p","text":"А ещё деньги. Не та абстрактная «экономия за год», которую считают в брошюрах, — а вполне конкретная. В кошельке в пятницу вечером лежит чуть больше, чем обычно. Ты не отслеживаешь это специально. Просто однажды замечаешь, что та купюра, которая раньше каждый день незаметно превращалась в дым, теперь остаётся с тобой."},{"type":"h","text":"Ты больше не привязан к пачке"},{"type":"p","text":"Помнишь это? Выходишь из дома — рука сама проверяет карман. Есть пачка? Сколько осталось? Хватит до вечера? А магазин по дороге работает? А если застрянешь в гостях, где нельзя выйти, — что тогда? Целая невидимая логистика, которую твоя голова прокручивала по сто раз на дню, а ты даже не замечал, сколько сил на это уходит."},{"type":"p","text":"Теперь этого нет. Можешь уехать за город на весь день и ни разу не подумать, где там ближайший ларёк. Можешь застрять в аэропорту на пять часов задержки — и тебя бесит только задержка, а не отсутствие места для курения. Свобода — это в том числе вот это: не зависеть от наличия маленькой коробки в кармане. Не строить день вокруг неё."},{"type":"p","text":"И самое странное — это ощущение контроля. Не того напряжённого «я держусь, я сильный», а спокойного. Реже выпадаешь из разговора на то самое «извини, я на минутку». Чаще остаёшься — весь, целиком, здесь. Тяга у кого-то ещё может зайти эпизодом и через месяцы, это нормально и не отменяет того, что внутри стало тише."},{"type":"h","text":"Тихая радость вместо вечной борьбы"},{"type":"p","text":"Поначалу свобода и правда ощущается как борьба. Первые дни — самые тяжёлые, тут честно: накатывает, тянет, хочется. Потом волны идут реже, становятся короче и слабее — день за днём, неделя за неделей. И в какой-то момент ты ловишь себя на том, что борьбы больше нет. Есть просто жизнь, в которой курения нет так же естественно, как нет в ней привычки грызть провода."},{"type":"p","text":"Если по дороге тебе помогал пластырь, таблетки от врача или что-то ещё — это часть твоей работы, а не звёздочка с пометкой «не считается». Помощь и твоя собственная перестройка головы шли в одной упряжке. Лестница довела тебя до этажа, но ноги по ступеням всё равно переставлял ты сам."},{"type":"p","text":"А если случилась одна затяжка на чужом балконе — это запись в дневнике, а не приговор. Где-то стоял триггер, который ты не разглядел: стресс, компания, рюмка, скука. Опаснее самой затяжки мысль «ну всё, поехали по новой» — именно она из одного эпизода лепит возвращение. Счётчик в приложении это понимает и не сбрасывает тебя в ноль. И ты сам себя не сбрасывай."},{"type":"h","text":"Перестаёшь считать дни"},{"type":"p","text":"Сначала ты считаешь. День третий, день десятый, месяц. Это нормально и даже полезно — цифры держат на плаву, когда штормит. У кого-то они остаются опорой надолго, и это тоже нормально. Но однажды ты замечаешь, что забыл посмотреть. Прошла неделя, а ты ни разу не вспомнил, какой по счёту сегодня день без сигарет."},{"type":"p","text":"И вот это — самый честный признак, что ты дошёл. Не цифра на экране, а то, что цифра перестала быть нужной. Ты больше не бывший курильщик, который героически держится. Ты просто человек, который живёт. Курение ушло из списка того, о чём надо думать, — туда же, где лежат вещи, которые тебя когда-то определяли, а теперь нет."},{"type":"p","text":"Дальше будет своя дорога — про неё в следующей главе. Но прямо сейчас стоит остановиться и заметить: ты уже здесь. По ту сторону. И тут, оказывается, просто хорошо живётся."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Вдохни носом — медленно, на четыре счёта — и поймай запах того, что вокруг тебя прямо в эту минуту: кофе, воздух из окна, чья-то еда, книга в руках. Просто отметь про себя: «я это чувствую». Раньше дым перебивал. Теперь — нет."},{"type":"p","text":"Это глава из книги — поддержка и опыт, а не медицинский совет. Любые препараты для отказа от курения — только по решению врача."}],
    takeawayRu: "Ты узнаешь, что свободен, не по дню на счётчике — а по тому утру, когда забыл на него посмотреть.",
  },
  {
    id: "whats-next", number: 20, icon: "leaf", color: "#5AC8FA", readMin: 5, part: "V. Свобода",
    titleRu: "Что дальше",
    leadRu: "Ты дочитал — теперь самое интересное начинается не на этих страницах, а в обычном дне.",
    bodyRu: [{"type":"p","text":"Закрой на секунду книгу — мысленно. Перелистни в голове всё, что прочитал, и проверь одно ощущение: тебе всё ещё кажется, что сигарета что-то тебе давала?"},{"type":"p","text":"Если кажется чуть меньше, чем неделю назад, — этого достаточно. Не нужно верить мне на сто процентов. Нужно только перестать верить старой версии истории, где никотин был твоим помощником, а не продавцом проблемы, которую сам же и создал."},{"type":"h","text":"Фокус ты уже видел изнутри"},{"type":"p","text":"Знаешь, что меняется, когда тебе один раз показали, как фокусник прячет монету в рукав? Трюк всё ещё ловкий. Но он больше не волшебство. Ты сидишь в зале и видишь движение локтя, которого раньше не замечал."},{"type":"p","text":"С тягой так же. Раньше она приходила как голос изнутри: «надо покурить, тогда отпустит». Теперь ты знаешь, чей это голос. Это не ты хочешь сигарету — это никотин, уходя из крови, теребит тебя за рукав и просит ещё дозу. Маленькое неудобство, которое притворяется большой нуждой."},{"type":"p","text":"Разоблачённый фокус не обязан перестать показываться. Он обязан перестать тобой управлять. И вот тут начинается роль приложения — не вместо тебя, а рядом."},{"type":"h","text":"Когда придёт волна"},{"type":"p","text":"Она придёт. Может, на второй день, у подъезда, где ты сто раз стоял с сигаретой. Может, на дружеском застолье, когда кто-то выйдет «подымить» и позовёт за компанию. Может, на работе, когда дедлайн и руки сами тянутся к привычному ритуалу-паузе."},{"type":"p","text":"В этот момент не надо ничего терпеть зубами. Открой Бриз. Там есть техники на острую тягу — короткие, на одну-две минуты, ровно на длину волны. Дыхание, пара вопросов к себе, способ занять руки и дотянуть до спада. Не «отвлекись и забудь», а провести тебя через минуту, пока она проходит сама."},{"type":"p","text":"Запиши волну в дневник тяги. Где был, что чувствовал, насколько сильно накрыло. Это не бюрократия. Через неделю-другую ты увидишь свои триггеры в лицо: «ага, меня цепляет не утренний кофе, а звонок матери» или «не вечер, а именно дорога с работы». Когда триггер назван, он наполовину обезврежен."},{"type":"p","text":"А если хочется не записать, а проговорить — есть помощник. Не для того, чтобы он тебя отчитал. Чтобы было кому в три часа ночи сказать «меня колотит, поговори со мной» — и получить нормальный человеческий ответ, а не пустую квартиру."},{"type":"h","text":"Каждая волна делает следующую слабее"},{"type":"p","text":"Про волны ты уже всё знаешь из прошлых глав — здесь добавлю только одно. Первая всегда кажется огромной просто потому, что ты её ещё не проживал без сигареты: нет опыта, что она спадёт сама. Прожил один раз — и спор закончен. Дальше у тебя за спиной доказательство, и каждая следующая волна ниже предыдущей не на словах, а на твоём собственном опыте."},{"type":"p","text":"Однажды ты ловишь себя на мысли, что забыл, когда накрывало в последний раз. Это история про дни и недели, а не про один героический вечер. Путь по дням в Бризе как раз про это: не «продержись», а «смотри, сколько ты уже прошёл»."},{"type":"p","text":"И если однажды оступишься — одна затяжка, одна сигарета на нервах, — не верь голосу, который тут же объявит: «всё, провалил, обнуляйся». Это тот же продавец, что и раньше, просто зашёл с другой стороны: раздул одну осечку до катастрофы, чтобы ты махнул рукой и вернулся к нему. Не давай ему этого. Счётчики в Бризе не сбрасываются от одного спотыкания, и ты тоже не списывай себя со счетов. Споткнулся — это споткнулся, а не упал обратно в курильщики."},{"type":"p","text":"И ещё, коротко, но важно. Если решишь подключить поддержку — пластырь, жвачку, что-то по рецепту, — это не белый флаг и не предательство всего, что ты тут прочитал. Это как снять фоновый гул, чтобы в тишине яснее расслышать те самые волны и спокойнее их переждать. Такие вещи помогают не взамен понимания, а в обнимку с ним. Только одно: всё рецептурное — через врача, на глаз тут гадать не стоит."},{"type":"h","text":"Длинный выдох"},{"type":"p","text":"Ты не бросаешь что-то хорошее. Ты возвращаешь себе то, что давно было твоим: ровное утро без першения, запах собственной кожи, деньги, которые раньше тлели по двадцать сантиметров за раз, и тихую гордость, которую не купишь."},{"type":"p","text":"Дальше начинается простая, нормальная жизнь некурящего человека — со своими мелочами, к которым ещё предстоит привыкнуть. А прямо сейчас сделай одну вещь, ради которой названо и приложение, и эта книга."},{"type":"p","text":"Сделай длинный, медленный выдох. Дольше, чем вдох. Почувствуй, как плечи опускаются. Воздух выходит из тебя свободно, целиком — впервые за долгое время ему ничего не мешает. Вот так. Это и есть начало."},{"type":"p","text":"И последнее, без чего нельзя: всё это — книга, которая идёт рядом и поддерживает, а не медицинский совет. С тем, что касается здоровья и препаратов, решай вместе с врачом."},{"type":"h","text":"Попробуй прямо сейчас"},{"type":"p","text":"Открой Бриз и поставь себе дату старта — сегодняшнюю. Просто отметь сегодняшний день как первый. Тридцать секунд, один тап — и у твоего пути появляется точка отсчёта, от которой будут считаться все прожитые волны."}],
    takeawayRu: "Тягу не надо побеждать — её надо пережить один раз, и она сама расскажет следующей, что здесь больше не наливают.",
  },
];

export function getChapter(id: string): BookChapter | undefined {
  return CHAPTERS.find((c) => c.id === id);
}

/** Тело главы на нужном языке с фолбэком на RU (EN пишем следующим заходом). */
export function chapterBody(ch: BookChapter, ru: boolean): BookBlock[] {
  return ru ? ch.bodyRu : (ch.bodyEn ?? ch.bodyRu);
}

/** Следующая глава по порядку (для кнопки «дальше» и свайпа). null на последней. */
export function nextChapter(id: string): BookChapter | null {
  const i = CHAPTERS.findIndex((c) => c.id === id);
  return i >= 0 && i < CHAPTERS.length - 1 ? CHAPTERS[i + 1] : null;
}

/** Сколько глав прочитано (по карте bookProgress: chapterId → ms). Интро не считаем «главой». */
export function readCount(progress: Record<string, number> | undefined): number {
  if (!progress) return 0;
  return CHAPTERS.filter((c) => c.number > 0 && progress[c.id]).length;
}

export const TOTAL_CHAPTERS = CHAPTERS.filter((c) => c.number > 0).length; // главы без интро

/** Части книги в порядке появления (для оглавления). */
export const BOOK_PARTS: string[] = CHAPTERS.reduce<string[]>((acc, c) => {
  if (!acc.includes(c.part)) acc.push(c.part);
  return acc;
}, []);

/** Глава, с которой продолжить: первая непрочитанная (или первая в книге). */
export function continueChapterId(progress: Record<string, number> | undefined): string {
  const p = progress ?? {};
  const firstUnread = CHAPTERS.find((c) => !p[c.id]);
  return (firstUnread ?? CHAPTERS[0]).id;
}
